loadstring("local repo = 'https://raw.githubusercontent.com/mstudio45/LinoriaLib/main/'\n\nlocal Library = loadstring(game:HttpGet(repo .. 'Library.lua'))()\nlocal ThemeManager = loadstring(game:HttpGet(repo .. 'addons/ThemeManager.lua'))()\nlocal SaveManager = loadstring(game:HttpGet(repo .. 'addons/SaveManager.lua'))()\nlocal Options = Library.Options\nlocal Toggles = Library.Toggles\n\nLibrary.ShowToggleFrameInKeybinds = true \nLibrary.ShowCustomCursor = true \nLibrary.NotifySide = \"Left\" \n\n\n\nlocal Window = Library:CreateWindow({\n\n\n\tTitle = 'SRX: CB:RO (by robert) | .gg/xbX9NzhqxC',\n\tCenter = true,\n\tAutoShow = true,\n\tResizable = true,\n\tShowCustomCursor = true,\n\tNotifySide = \"Left\",\n\tTabPadding = 8,\n\tMenuFadeTime = 0.2\n})\n\n\n-- BdB2AeB2 AaAeA4 AfB0A0A2A8AbBcAdBbA9\nlocal Tabs = {\n    Aim = Window:AddTab('Aim'),\n\tAntiAim = Window:AddTab('Anti Aim'),\n\tVisuals = Window:AddTab('Visuals'),\n\tMisc = Window:AddTab('Misc'),\n    [\"UI Settings\"] = Window:AddTab('UI Settings'),\n}\n\nlocal RightGroupBox = Tabs.Visuals:AddLeftGroupbox('Bullet Tracer')\n\nRightGroupBox:AddToggle('Bullet tracer', {\n\tText = 'Bullet tracer',\n\tTooltip = 'Bullet tracer', \n\tDisabledTooltip = 'Bulle tracer', \n\tCallback = function(Value)\n \t\tprint('bullet tracers enabled')\n\tend\n})\n\nRightGroupBox:AddSlider('Bullet tracer life time', {\n\tText = 'Bullet tracer life time',\n\tDefault = 0.22,\n\tMin = 0,\n\tMax = 20,\n\tRounding = 1,\n\tCompact = false,\n\n\tCallback = function(s)\n\t\tgame:GetService(\"ReplicatedStorage\").VisualizeModule.Trail.Lifetime = s \n\tend,\n\n\tTooltip = 'I am changer trail life time', \n\tDisabledTooltip = 'I am disabled!', \n\n\tDisabled = false, \n\tVisible = true, \n})\n\n\nRightGroupBox:AddSlider('Bullet tracer brightness', {\n\tText = 'Bullet tracer brightness',\n\tDefault = 5,\n\tMin = 0,\n\tMax = 20,\n\tRounding = 1,\n\tCompact = false,\n\n\tCallback = function(ass)\n\t\tgame:GetService(\"ReplicatedStorage\").VisualizeModule.Trail.Brightness = ass \n\tend,\n\n\tTooltip = 'I am changer brightness ', \n\tDisabledTooltip = 'I am disabled!', \n\n\tDisabled = false, \n\tVisible = true, \n})\n\n\nRightGroupBox:AddSlider('Bullet tracer length', {\n\tText = 'Bullet tracer length',\n\tDefault = 66,\n\tMin = 0,\n\tMax = 150,\n\tRounding = 1,\n\tCompact = false,\n\n\tCallback = function(ass)\n\t\tgame:GetService(\"ReplicatedStorage\").VisualizeModule.Trail.MaxLength = ass \n\tend,\n\n\tTooltip = 'I am changer length tracer ', \n\tDisabledTooltip = 'I am disabled!', \n\n\tDisabled = false, \n\tVisible = true, \n})\n\nlocal LeftGroupBox = Tabs.Visuals:AddLeftGroupbox('Esp')\n\n\n-- =========================================================================\n-- A8B1AfB0A0A2AbA5AdAdBbA9 A8 AeAfB2A8AcA8A7A8B0AeA2A0AdAdBbA9 AaAeA4 A4AbBf A2AaAbA0A4AaA8 VISUALS -> ESP\n-- =========================================================================\n\n-- B8A0A3 1: AeC1DaDfC2CbDfC5Cc CeC1D9C8C5 D1C5D0C2C8D1Db AeA4A8Ad B0A0A7 C2 CdC0D7C0CbC5 D1CaD0C8CfD2C0 (C8CbC8 CfC5D0C5C4 DdD2C8Cc C1CbCeCaCeCc)\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal LocalPlayer = Players.LocalPlayer\nlocal Camera = workspace.CurrentCamera\n\n-- B1CeC7C4C0E1Cc C3D0D3CfCfD3 C4CbDf ESP\n\n\n-- B8A0A3 2: AaC0C6C4D3De D4D3CdCaD6C8De CeC1CeD0C0D7C8C2C0C5Cc C2 C1CbCeCa do...end\n\n-- Box ESP\ndo\n    local ESP = {\n        Enabled = false,\n        TextSize = 14,\n        BoxThickness = 2,\n        Color = Color3.fromRGB(255, 255, 255),\n        TeamCheck = true\n    }\n    local ESPObjects = {}\n\n    local function CreateESPForPlayer(player)\n        if player == LocalPlayer then return end\n        local espObject = {}\n        espObject.Box = Drawing.new(\"Square\")\n        espObject.Box.Visible = false\n        espObject.Box.Thickness = ESP.BoxThickness\n        espObject.Box.Filled = false\n        espObject.Box.Color = ESP.Color\n        ESPObjects[player] = espObject\n        player.AncestryChanged:Connect(function()\n            if not player:IsDescendantOf(game) and ESPObjects[player] then\n                espObject.Box:Remove()\n                ESPObjects[player] = nil\n            end\n        end)\n    end\n\n    for _, player in pairs(Players:GetPlayers()) do CreateESPForPlayer(player) end\n    Players.PlayerAdded:Connect(CreateESPForPlayer)\n    Players.PlayerRemoving:Connect(function(player)\n        if ESPObjects[player] then\n            ESPObjects[player].Box:Remove()\n            ESPObjects[player] = nil\n        end\n    end)\n\n    RunService.RenderStepped:Connect(function()\n        if not ESP.Enabled then\n            for _, espObject in pairs(ESPObjects) do espObject.Box.Visible = false end\n            return\n        end\n        for player, espObject in pairs(ESPObjects) do\n            if ESP.TeamCheck and player.Team == LocalPlayer.Team then\n                espObject.Box.Visible = false\n                continue\n            end\n            local character = player.Character\n            if character and character.PrimaryPart and character:FindFirstChild(\"Humanoid\") then\n                local vector, onScreen = Camera:WorldToViewportPoint(character.PrimaryPart.Position)\n                if onScreen then\n                    local topPos = character.PrimaryPart.Position + Vector3.new(0, 3, 0)\n                    local bottomPos = character.PrimaryPart.Position - Vector3.new(0, 3, 0)\n                    local topVector = Camera:WorldToViewportPoint(topPos)\n                    local bottomVector = Camera:WorldToViewportPoint(bottomPos)\n                    local height = math.abs(topVector.Y - bottomVector.Y)\n                    local width = height * 0.6\n                    espObject.Box.Position = Vector2.new(vector.X - width / 2, vector.Y - height / 2)\n                    espObject.Box.Size = Vector2.new(width, height)\n                    espObject.Box.Visible = true\n                else\n                    espObject.Box.Visible = false\n                end\n            else\n                espObject.Box.Visible = false\n            end\n        end\n    end)\n\n    LeftGroupBox:AddToggle('BoxEsp', {\n        Text = 'Box ESP',\n        Tooltip = 'Box esp',\n        Callback = function(Value) ESP.Enabled = Value end\n    })\nend\n\n-- Health Bar ESP\ndo\n    local ESP = { Enabled = false, TeamCheck = true }\n    local ESPObjects = {}\n    local function GetHealthColor(healthPercent) return Color3.new(1 - healthPercent, healthPercent, 0) end\n    local function CreateESPForPlayer(player)\n        if player == LocalPlayer then return end\n        local espObject = {}\n        espObject.HealthBG = Drawing.new(\"Square\")\n        espObject.HealthBG.Visible = false\n        espObject.HealthBG.Filled = true\n        espObject.HealthBG.Color = Color3.fromRGB(60, 60, 60)\n        espObject.HealthFill = Drawing.new(\"Square\")\n        espObject.HealthFill.Visible = false\n        espObject.HealthFill.Filled = true\n        ESPObjects[player] = espObject\n        player.AncestryChanged:Connect(function()\n            if not player:IsDescendantOf(game) and ESPObjects[player] then\n                espObject.HealthBG:Remove()\n                espObject.HealthFill:Remove()\n                ESPObjects[player] = nil\n            end\n        end)\n    end\n\n    for _, player in pairs(Players:GetPlayers()) do CreateESPForPlayer(player) end\n    Players.PlayerAdded:Connect(CreateESPForPlayer)\n    Players.PlayerRemoving:Connect(function(player)\n        if ESPObjects[player] then\n            ESPObjects[player].HealthBG:Remove()\n            ESPObjects[player].HealthFill:Remove()\n            ESPObjects[player] = nil\n        end\n    end)\n\n    RunService.RenderStepped:Connect(function()\n        if not ESP.Enabled then\n            for _, obj in pairs(ESPObjects) do\n                obj.HealthBG.Visible = false\n                obj.HealthFill.Visible = false\n            end\n            return\n        end\n        for player, espObject in pairs(ESPObjects) do\n            local character = player.Character\n            if not character or not character.PrimaryPart or not character:FindFirstChild(\"Humanoid\") or (ESP.TeamCheck and player.Team == LocalPlayer.Team) then\n                espObject.HealthBG.Visible = false\n                espObject.HealthFill.Visible = false\n                continue\n            end\n            local humanoid = character.Humanoid\n            local vector, onScreen = Camera:WorldToViewportPoint(character.PrimaryPart.Position)\n            if onScreen then\n                local topPos = character.PrimaryPart.Position + Vector3.new(0, 3, 0)\n                local bottomPos = character.PrimaryPart.Position - Vector3.new(0, 3, 0)\n                local topVector = Camera:WorldToViewportPoint(topPos)\n                local bottomVector = Camera:WorldToViewportPoint(bottomPos)\n                local height = math.abs(topVector.Y - bottomVector.Y)\n                local healthPercent = math.clamp(humanoid.Health / humanoid.MaxHealth, 0, 1)\n                espObject.HealthBG.Size = Vector2.new(4, height)\n                espObject.HealthBG.Position = Vector2.new(vector.X + height * 0.3 + 3, vector.Y - height / 2)\n                espObject.HealthBG.Visible = true\n                espObject.HealthFill.Size = Vector2.new(4, height * healthPercent)\n                espObject.HealthFill.Position = Vector2.new(vector.X + height * 0.3 + 3, vector.Y - height / 2 + (height - height * healthPercent))\n                espObject.HealthFill.Color = GetHealthColor(healthPercent)\n                espObject.HealthFill.Visible = true\n            else\n                espObject.HealthBG.Visible = false\n                espObject.HealthFill.Visible = false\n            end\n        end\n    end)\n\n    LeftGroupBox:AddToggle('Health Bar', {\n        Text = 'Health Bar',\n        Tooltip = 'health bar',\n        Callback = function(Value) ESP.Enabled = Value end\n    })\nend\n\n-- Name ESP\ndo\n    local NameESP = { Enabled = false, TeamCheck = true, HeightOffset = 4.65 }\n    local ESPNames = {}\n\n    local function CreateNameESP(player)\n        if player == LocalPlayer then return end\n        local text = Drawing.new(\"Text\")\n        text.Visible, text.Center, text.Outline, text.Font = false, true, false, 2\n        text.Color, text.Size = Color3.fromRGB(255, 255, 255), 14\n        ESPNames[player] = text\n        player.AncestryChanged:Connect(function()\n            if not player:IsDescendantOf(game) and ESPNames[player] then\n                text:Remove()\n                ESPNames[player] = nil\n            end\n        end)\n    end\n\n    for _, player in pairs(Players:GetPlayers()) do CreateNameESP(player) end\n    Players.PlayerAdded:Connect(CreateNameESP)\n    Players.PlayerRemoving:Connect(function(player)\n        if ESPNames[player] then\n            ESPNames[player]:Remove()\n            ESPNames[player] = nil\n        end\n    end)\n\n    RunService.RenderStepped:Connect(function()\n        if not NameESP.Enabled then\n            for _, text in pairs(ESPNames) do text.Visible = false end\n            return\n        end\n        for player, text in pairs(ESPNames) do\n            local character = player.Character\n            if not character or not character.PrimaryPart or (NameESP.TeamCheck and player.Team == LocalPlayer.Team) then\n                text.Visible = false\n                continue\n            end\n            local headPos = character.PrimaryPart.Position + Vector3.new(0, NameESP.HeightOffset, 0)\n            local vector, onScreen = Camera:WorldToViewportPoint(headPos)\n            if onScreen then\n                text.Position, text.Text, text.Visible = Vector2.new(vector.X, vector.Y), player.Name, true\n            else\n                text.Visible = false\n            end\n        end\n    end)\n\n    LeftGroupBox:AddToggle('Name ESP', {\n        Text = 'Name ESP',\n        Tooltip = 'Name esp',\n        Callback = function(Value) NameESP.Enabled = Value end\n    })\nend\n\n-- A8 D2C0Ca C4C0CbC5C5 C4CbDf CeD1D2C0CbDcCdDbD5 D4D3CdCaD6C8C9 ESP...\n-- ... (Distance, Skeleton, Chams, Health Text) ...\n-- AfD0CeD1D2Ce CfD0CeC4CeCbC6C0C9 CeC1CeD0C0D7C8C2C0D2Dc CaC0C6C4D3De C8C7 CdC8D5 C2 D1C2CeC9 C1CbCeCa do...end\n\n\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Camera = workspace.CurrentCamera\nlocal LocalPlayer = Players.LocalPlayer\n\n-- &99þ0f AaCeCdD4C8C3D3D0C0D6C8Df Distance ESP\nlocal DistanceESP = {\n    Enabled = false,\n    MaxDistance = 500000,\n    TeamCheck = true, -- '05 AdC5 CfCeCaC0C7DbC2C0D2Dc D1CeDeC7CdC8CaCeC2\n    TextSize = 14,\n    TextColor = Color3.fromRGB(200, 200, 200),\n    Outline = true,\n    HeightOffset = -3 -- Ø3dÜcf B0C0D1CfCeCbCeC6C5CdC8C5 CfCeC4 CfC5D0D1CeCdC0C6C5Cc (CcC5CdDcD8C5 = CdC8C6C5)\n}\n\n-- B5D0C0CdC8CbC8D9C5 CeC1DaC5CaD2CeC2\nlocal ESPDistance = {}\n\n-- Ø3eÝf1 B4D3CdCaD6C8Df C4CbDf D1CeC7C4C0CdC8Df Distance ESP\nlocal function CreateDistanceESP(player)\n    if player == LocalPlayer then return end\n\n    local text = Drawing.new(\"Text\")\n    text.Visible = false\n    text.Center = true\n    text.Outline = DistanceESP.Outline\n    text.Color = DistanceESP.TextColor\n    text.Size = DistanceESP.TextSize\n    text.Font = 2\n\n    ESPDistance[player] = text\n\n    player.AncestryChanged:Connect(function()\n        if not player:IsDescendantOf(game) then\n            text:Remove()\n            ESPDistance[player] = nil\n        end\n    end)\nend\n\n-- B1CeC7C4C0E1Cc C4CbDf C2D1C5D5 D1D3D9C5D1D2C2D3DeD9C8D5 C8C3D0CeCaCeC2\nfor _, player in pairs(Players:GetPlayers()) do\n    if player ~= LocalPlayer then\n        CreateDistanceESP(player)\n    end\nend\n\n-- A4CbDf CdCeC2DbD5 C8C3D0CeCaCeC2\nPlayers.PlayerAdded:Connect(CreateDistanceESP)\n\n-- B3C4C0CbDfC5Cc CfD0C8 C2DbD5CeC4C5\nPlayers.PlayerRemoving:Connect(function(player)\n    if ESPDistance[player] then\n        ESPDistance[player]:Remove()\n        ESPDistance[player] = nil\n    end\nend)\n\n-- Ø3cß00 AeD1CdCeC2CdCeC9 C0CfC4C5C9D2 ESP\nRunService.RenderStepped:Connect(function()\n    if not DistanceESP.Enabled then\n        for _, text in pairs(ESPDistance) do\n            text.Visible = false\n        end\n        return\n    end\n\n    for player, text in pairs(ESPDistance) do\n        local character = player.Character\n        if not character or not character:FindFirstChild(\"HumanoidRootPart\") then\n            text.Visible = false\n            continue\n        end\n\n        -- '05 Team Check (CdC5 CfCeCaC0C7DbC2C0D2Dc D1CeDeC7CdC8CaCeC2)\n        if DistanceESP.TeamCheck and player.Team == LocalPlayer.Team and not player.Neutral then\n            text.Visible = false\n            continue\n        end\n\n        local root = character.HumanoidRootPart\n        local offsetPos = root.Position + Vector3.new(0, DistanceESP.HeightOffset, 0) -- +07þ0f CfCeC4 CfC5D0D1CeCdC0C6C5Cc\n        local vector, onScreen = Camera:WorldToViewportPoint(offsetPos)\n        local distance = (root.Position - Camera.CFrame.Position).Magnitude\n\n        if onScreen and distance <= DistanceESP.MaxDistance then\n            text.Position = Vector2.new(vector.X, vector.Y)\n            text.Text = string.format(\"%.0f m\", distance) -- Ø3dÜcf CeCaD0D3C3CbE1CdCdC0Df C4C8D1D2C0CdD6C8Df C2 CcC5D2D0C0D5\n            text.Visible = true\n        else\n            text.Visible = false\n        end\n    end\nend)\n\n-- '05 UI: B2CeC3C3Cb\nLeftGroupBox:AddToggle('Distance ESP', {\n    Text = 'Distance ESP',\n    Tooltip = 'Distance Esp',\n    Callback = function(Value)\n        DistanceESP.Enabled = Value\n    end\n})\n\n-- Skeleton ESP (Full, Fixed, with UI Toggle)\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Camera = workspace.CurrentCamera\nlocal LocalPlayer = Players.LocalPlayer\n\n-- AdC0D1D2D0CeC9CaC8\nlocal Settings = {\n    Color = Color3.fromRGB(255, 255, 255),\n    Thickness = 1.5,\n    Transparency = 1,\n    MaxDistance = 1000,\n    TeamCheck = true, -- true = CdC5 CfCeCaC0C7DbC2C0D2Dc D2C8CcCcC5C9D2CeC2\n}\n\nlocal ESPs = {}\nlocal SkeletonESPEnabled = false -- D2C5CfC5D0Dc CfCe D3CcCeCbD7C0CdC8De C2DbCaCbDeD7C5CdCe\n\n-- B1CeC7C4C0CdC8C5 CbC8CdC8C8\nlocal function newLine()\n    local l = Drawing.new(\"Line\")\n    l.Visible = false\n    l.Color = Settings.Color\n    l.Thickness = Settings.Thickness\n    l.Transparency = Settings.Transparency\n    return l\nend\n\n-- B3C4C0CbC5CdC8C5 ESP C8C3D0CeCaC0\nlocal function removeESP(player)\n    if ESPs[player] then\n        for _, line in pairs(ESPs[player]) do\n            if line then\n                line:Remove()\n            end\n        end\n        ESPs[player] = nil\n    end\nend\n\n-- B1CeC7C4C0CdC8C5 ESP\nlocal function createESP(player)\n    if player == LocalPlayer then return end\n    removeESP(player)\n\n    task.spawn(function()\n        while player and player.Parent == Players do\n            if not SkeletonESPEnabled then\n                task.wait(0.5)\n                continue\n            end\n\n            local character = player.Character\n            if not character or not character:FindFirstChild(\"HumanoidRootPart\") then\n                task.wait(1)\n                continue\n            end\n\n            local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n            if not humanoid or humanoid.Health <= 0 then\n                task.wait(1)\n                continue\n            end\n\n            local rigType = humanoid.RigType\n            local bones = {}\n\n            if rigType == Enum.HumanoidRigType.R15 then\n                bones = {\n                    {\"Head\", \"UpperTorso\"},\n                    {\"UpperTorso\", \"LowerTorso\"},\n                    {\"UpperTorso\", \"LeftUpperArm\"},\n                    {\"LeftUpperArm\", \"LeftLowerArm\"},\n                    {\"LeftLowerArm\", \"LeftHand\"},\n                    {\"UpperTorso\", \"RightUpperArm\"},\n                    {\"RightUpperArm\", \"RightLowerArm\"},\n                    {\"RightLowerArm\", \"RightHand\"},\n                    {\"LowerTorso\", \"LeftUpperLeg\"},\n                    {\"LeftUpperLeg\", \"LeftLowerLeg\"},\n                    {\"LeftLowerLeg\", \"LeftFoot\"},\n                    {\"LowerTorso\", \"RightUpperLeg\"},\n                    {\"RightUpperLeg\", \"RightLowerLeg\"},\n                    {\"RightLowerLeg\", \"RightFoot\"},\n                }\n            else\n                bones = {\n                    {\"Head\", \"Torso\"},\n                    {\"Torso\", \"Left Arm\"},\n                    {\"Torso\", \"Right Arm\"},\n                    {\"Torso\", \"Left Leg\"},\n                    {\"Torso\", \"Right Leg\"},\n                }\n            end\n\n            -- D1CeC7C4C0E1Cc CbC8CdC8C8\n            ESPs[player] = {}\n            for _, pair in pairs(bones) do\n                local line = newLine()\n                ESPs[player][pair[1] .. \"_\" .. pair[2]] = line\n            end\n\n            -- RenderStepped CeC1CdCeC2CbC5CdC8C5\n            local conn\n            conn = RunService.RenderStepped:Connect(function()\n                if not SkeletonESPEnabled then\n                    for _, l in pairs(ESPs[player]) do\n                        l.Visible = false\n                    end\n                    return\n                end\n\n                local char = player.Character\n                if not char or not char:FindFirstChild(\"Humanoid\") or char.Humanoid.Health <= 0 then\n                    removeESP(player)\n                    conn:Disconnect()\n                    return\n                end\n\n                -- B2C8Cc-D7C5Ca\n                if Settings.TeamCheck and player.Team == LocalPlayer.Team and player.Team ~= nil then\n                    for _, l in pairs(ESPs[player]) do\n                        l.Visible = false\n                    end\n                    return\n                end\n\n                local root = char:FindFirstChild(\"HumanoidRootPart\")\n                if not root then return end\n\n                local _, onScreen = Camera:WorldToViewportPoint(root.Position)\n                if not onScreen then\n                    for _, l in pairs(ESPs[player]) do\n                        l.Visible = false\n                    end\n                    return\n                end\n\n                local distance = (root.Position - Camera.CFrame.Position).Magnitude\n                if distance > Settings.MaxDistance then\n                    for _, l in pairs(ESPs[player]) do\n                        l.Visible = false\n                    end\n                    return\n                end\n\n                -- CeC1CdCeC2CbC5CdC8C5 CbC8CdC8C9\n                for _, pair in pairs(bones) do\n                    local partA = char:FindFirstChild(pair[1])\n                    local partB = char:FindFirstChild(pair[2])\n                    local line = ESPs[player][pair[1] .. \"_\" .. pair[2]]\n                    if partA and partB and line then\n                        local a, visA = Camera:WorldToViewportPoint(partA.Position)\n                        local b, visB = Camera:WorldToViewportPoint(partB.Position)\n                        if visA or visB then\n                            line.From = Vector2.new(a.X, a.Y)\n                            line.To = Vector2.new(b.X, b.Y)\n                            line.Visible = true\n                        else\n                            line.Visible = false\n                        end\n                    elseif line then\n                        line.Visible = false\n                    end\n                end\n            end)\n\n            -- CeD7C8D1D2CaC0 CfD0C8 C2DbD5CeC4C5 C8C3D0CeCaC0\n            player.AncestryChanged:Connect(function(_, parent)\n                if not parent then\n                    conn:Disconnect()\n                    removeESP(player)\n                end\n            end)\n\n            break\n        end\n    end)\nend\n\n-- B1CeC7C4C0E1Cc ESP C4CbDf C2D1C5D5 D2C5CaD3D9C8D5 C8C3D0CeCaCeC2\nfor _, player in pairs(Players:GetPlayers()) do\n    if player ~= LocalPlayer then\n        createESP(player)\n    end\nend\n\n-- AdCeC2DbC5 C8C3D0CeCaC8\nPlayers.PlayerAdded:Connect(createESP)\nPlayers.PlayerRemoving:Connect(removeESP)\n\n-- ================== UI Toggle ==================\nLeftGroupBox:AddToggle('Skeleton Esp', {\n    Text = 'Skeleton ESP',\n    Tooltip = 'Toggle Skeleton ESP',\n    Callback = function(Value)\n        SkeletonESPEnabled = Value\n        for _, playerLines in pairs(ESPs) do\n            for _, line in pairs(playerLines) do\n                line.Visible = Value\n            end\n        end\n    end\n})\n\n\n\n\n\n\n\n\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\nlocal RunService = game:GetService(\"RunService\")\nlocal Camera = workspace.CurrentCamera\n\nlocal ChamsEnabled = false\n\n-- B6C2C5D2C0\nlocal VisibleColor = Color3.fromRGB(0, 255, 0)\nlocal HiddenColor = Color3.fromRGB(255, 0, 0)\n\n-- B1CeC7C4C0CdC8C5 Highlight\nlocal function createHighlight(character)\n    if character:FindFirstChild(\"ChamHighlight\") then\n        character.ChamHighlight:Destroy()\n    end\n\n    local highlight = Instance.new(\"Highlight\")\n    highlight.Name = \"ChamHighlight\"\n    highlight.Adornee = character\n    highlight.FillColor = VisibleColor\n    highlight.OutlineColor = Color3.fromRGB(0, 0, 0)\n    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop\n    highlight.FillTransparency = 0.3\n    highlight.OutlineTransparency = 0.2\n    highlight.Parent = character\n    return highlight\nend\n\n-- AeC1CdCeC2CbC5CdC8C5 D6C2C5D2C0\nlocal function updateHighlight(highlight, character)\n    if not character or not highlight then return end\n    local root = character:FindFirstChild(\"HumanoidRootPart\")\n    if not root then return end\n\n    -- AfD0CeC2C5D0CaC0 D2C8Cc-D7C5CaC0\n    local player = Players:GetPlayerFromCharacter(character)\n    if player and player.Team == LocalPlayer.Team then\n        highlight.Enabled = false\n        return\n    else\n        highlight.Enabled = true\n    end\n\n    -- AfD0CeC2C5D0CaC0 C2C8C4C8CcCeD1D2C8\n    local ray = Ray.new(Camera.CFrame.Position, (root.Position - Camera.CFrame.Position).Unit * (root.Position - Camera.CFrame.Position).Magnitude)\n    local part, _ = workspace:FindPartOnRayWithIgnoreList(ray, {LocalPlayer.Character}, false, true)\n    if part and part:IsDescendantOf(character) then\n        highlight.FillColor = VisibleColor\n    else\n        highlight.FillColor = HiddenColor\n    end\nend\n\n-- AdC0D1D2D0CeC9CaC0 C8C3D0CeCaC0\nlocal function setupPlayer(player)\n    if player == LocalPlayer then return end\n\n    local function onCharacter(char)\n        task.wait(0.1)\n        if not ChamsEnabled then return end\n\n        local highlight = createHighlight(char)\n\n        local conn\n        conn = RunService.RenderStepped:Connect(function()\n            if not highlight or not highlight.Parent then\n                conn:Disconnect()\n                return\n            end\n            updateHighlight(highlight, char)\n        end)\n    end\n\n    if player.Character then onCharacter(player.Character) end\n    player.CharacterAdded:Connect(onCharacter)\nend\n\nfor _, p in ipairs(Players:GetPlayers()) do\n    setupPlayer(p)\nend\nPlayers.PlayerAdded:Connect(setupPlayer)\n\n-----------------------------------------------------\n-- Ø3eÝe9 UI D7C0D1D2Dc\n-----------------------------------------------------\nLeftGroupBox:AddToggle('ChamsESP', {\n    Text = 'Chams ESP',\n    Tooltip = 'chams esp',\n    Callback = function(Value)\n        ChamsEnabled = Value\n        if not Value then\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer and player.Character then\n                    local h = player.Character:FindFirstChild(\"ChamHighlight\")\n                    if h then h:Destroy() end\n                end\n            end\n        else\n            for _, player in ipairs(Players:GetPlayers()) do\n                setupPlayer(player)\n            end\n        end\n    end\n})\n\n-- Ø3cßa8 B1CbC0C9C4C5D0Db C4CbDf C2C8C4C8CcDbD5 chams\nLeftGroupBox:AddLabel(\"The color of the chams is not beyond the wall\")\nLeftGroupBox:AddSlider('VisibleR', {Text = 'Red (R)', Default = 0, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    VisibleColor = Color3.fromRGB(v, VisibleColor.G * 255, VisibleColor.B * 255)\nend})\nLeftGroupBox:AddSlider('VisibleG', {Text = 'Green (G)', Default = 255, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    VisibleColor = Color3.fromRGB(VisibleColor.R * 255, v, VisibleColor.B * 255)\nend})\nLeftGroupBox:AddSlider('VisibleB', {Text = 'Blue (B)', Default = 0, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    VisibleColor = Color3.fromRGB(VisibleColor.R * 255, VisibleColor.G * 255, v)\nend})\n\n-- Ø3dÝ34 B1CbC0C9C4C5D0Db C4CbDf D1CaD0DbD2DbD5 (C7C0 D1D2C5CdCeC9)\nLeftGroupBox:AddLabel(\"The color of the chams is  beyond the wall\")\nLeftGroupBox:AddSlider('HiddenR', {Text = 'Red (R)', Default = 255, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    HiddenColor = Color3.fromRGB(v, HiddenColor.G * 255, HiddenColor.B * 255)\nend})\nLeftGroupBox:AddSlider('HiddenG', {Text = 'Green (G)', Default = 0, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    HiddenColor = Color3.fromRGB(HiddenColor.R * 255, v, HiddenColor.B * 255)\nend})\nLeftGroupBox:AddSlider('HiddenB', {Text = 'Blue (B)', Default = 0, Min = 0, Max = 255, Rounding = 0, Callback = function(v)\n    HiddenColor = Color3.fromRGB(HiddenColor.R * 255, HiddenColor.G * 255, v)\nend})\n\n\n\n\n\n\n\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Camera = workspace.CurrentCamera\nlocal LocalPlayer = Players.LocalPlayer\n\n-- &99þ0f AdC0D1D2D0CeC9CaC8\nlocal HealthTextESP = {\n    Enabled = false,\n    MaxDistance = 5000,\n    TeamCheck = true,\n    BaseYOffset = 4.4,   -- C1C0C7CeC2CeC5 D1CcC5D9C5CdC8C5 C2CdC8C7\n    MinYOffset = 2.8,    -- CcC8CdC8CcC0CbDcCdCeC5 (CaCeC3C4C0 C1CbC8C7CaCe)\n    MaxYOffset = 6.5,    -- CcC0CaD1C8CcC0CbDcCdCeC5 (CaCeC3C4C0 C4C0CbC5CaCe)\n    ScaleStart = 10,     -- CeD2CaD3C4C0 CdC0D7C8CdC0C5D2 CcC5CdDfD2DcD1Df\n    ScaleEnd = 200       -- CdC0 CaC0CaCeCc D0C0D1D1D2CeDfCdC8C8 C4CeD1D2C8C3C0C5D2 MaxYOffset\n}\n\nlocal ESPTexts = {}\n\n-- Ø3dÜe6 B1CeC7C4C0CdC8C5 D2C5CaD1D2C0\nlocal function createHealthText(player)\n    if player == LocalPlayer then return end\n\n    local drawing = Drawing.new(\"Text\")\n    drawing.Visible = false\n    drawing.Center = true\n    drawing.Size = 12\n    drawing.Color = Color3.fromRGB(255, 255, 255)\n    drawing.Outline = true\n    drawing.OutlineColor = Color3.fromRGB(0, 0, 0)\n    drawing.Text = \"0 HP\"\n\n    ESPTexts[player] = drawing\n\n    player.AncestryChanged:Connect(function(_, parent)\n        if not parent then\n            drawing:Remove()\n            ESPTexts[player] = nil\n        end\n    end)\nend\n\n-- B1CeC7C4C0CdC8C5 C4CbDf C2D1C5D5 C8C3D0CeCaCeC2\nfor _, player in pairs(Players:GetPlayers()) do\n    if player ~= LocalPlayer then\n        createHealthText(player)\n    end\nend\n\n-- AdCeC2DbC9 C8C3D0CeCa\nPlayers.PlayerAdded:Connect(function(player)\n    if player ~= LocalPlayer then\n        createHealthText(player)\n    end\nend)\n\n-- B3C4C0CbC5CdC8C5 CfD0C8 C2DbD5CeC4C5\nPlayers.PlayerRemoving:Connect(function(player)\n    if ESPTexts[player] then\n        ESPTexts[player]:Remove()\n        ESPTexts[player] = nil\n    end\nend)\n\n-- Ø3dÝ04 AeC1CdCeC2CbC5CdC8C5 CaC0C6C4DbC9 CaC0C4D0\nRunService.RenderStepped:Connect(function()\n    for player, text in pairs(ESPTexts) do\n        local char = player.Character\n        if not HealthTextESP.Enabled or not char or not char:FindFirstChild(\"HumanoidRootPart\") or not char:FindFirstChild(\"Humanoid\") then\n            text.Visible = false\n            continue\n        end\n\n        if HealthTextESP.TeamCheck and player.Team == LocalPlayer.Team then\n            text.Visible = false\n            continue\n        end\n\n        local root = char.HumanoidRootPart\n        local humanoid = char.Humanoid\n        local dist = (Camera.CFrame.Position - root.Position).Magnitude\n\n        if dist <= HealthTextESP.MaxDistance then\n            local pos, onScreen = Camera:WorldToViewportPoint(\n                root.Position - Vector3.new(0,\n                    math.clamp(\n                        HealthTextESP.MinYOffset + (HealthTextESP.MaxYOffset - HealthTextESP.MinYOffset) * ((dist - HealthTextESP.ScaleStart) / (HealthTextESP.ScaleEnd - HealthTextESP.ScaleStart)),\n                        HealthTextESP.MinYOffset,\n                        HealthTextESP.MaxYOffset\n                    ),\n                    0\n                )\n            )\n\n            if onScreen then\n                local hp = math.floor(humanoid.Health)\n                text.Text = tostring(hp) .. \" HP\"\n                text.Position = Vector2.new(pos.X, pos.Y)\n                text.Visible = true\n            else\n                text.Visible = false\n            end\n        else\n            text.Visible = false\n        end\n    end\nend)\n\n-- '05 AaCdCeCfCaC0 C2 CbC5C2CeCc UI\nLeftGroupBox:AddToggle('Health Text ESP', {\n    Text = 'Health Text ESP',\n    Tooltip = 'Shows player HP below them (distance adaptive)',\n    Callback = function(Value)\n        HealthTextESP.Enabled = Value\n    end\n})\n\n\n\n\nlocal RightGroupBox = Tabs.Visuals:AddRightGroupbox('Another')\n\n\n\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\n\nlocal NoRenderTeamEnabled = false\nlocal hiddenTeammates = {}\n\n-- B1CaD0DbD2Dc CcCeC4C5CbDc CfC5D0D1CeCdC0C6C0\nlocal function hideCharacter(char)\n\tif not char or hiddenTeammates[char] then return end\n\thiddenTeammates[char] = true\n\n\tfor _, part in ipairs(char:GetDescendants()) do\n\t\tif part:IsA(\"BasePart\") or part:IsA(\"Decal\") then\n\t\t\tpart.LocalTransparencyModifier = 1\n\t\tend\n\tend\nend\n\n-- AfCeCaC0C7C0D2Dc CeC1D0C0D2CdCe\nlocal function showCharacter(char)\n\tif not char or not hiddenTeammates[char] then return end\n\thiddenTeammates[char] = nil\n\n\tfor _, part in ipairs(char:GetDescendants()) do\n\t\tif part:IsA(\"BasePart\") or part:IsA(\"Decal\") then\n\t\t\tpart.LocalTransparencyModifier = 0\n\t\tend\n\tend\nend\n\n-- AeC1CdCeC2C8D2Dc C2D1C5D5 C8C3D0CeCaCeC2\nlocal function updateAllPlayers()\n\tfor _, plr in ipairs(Players:GetPlayers()) do\n\t\tif plr ~= LocalPlayer and plr.Character then\n\t\t\tif NoRenderTeamEnabled and plr.Team == LocalPlayer.Team then\n\t\t\t\thideCharacter(plr.Character)\n\t\t\telse\n\t\t\t\tshowCharacter(plr.Character)\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- AeC1CdCeC2CbC5CdC8C5 CfD0C8 D1CcC5CdC5 D2C8CcDb C8CbC8 CfC5D0D1CeCdC0C6C0\nPlayers.PlayerAdded:Connect(function(plr)\n\tplr:GetPropertyChangedSignal(\"Team\"):Connect(updateAllPlayers)\n\tplr.CharacterAdded:Connect(function()\n\t\ttask.wait(0.1)\n\t\tupdateAllPlayers()\n\tend)\nend)\n\nLocalPlayer:GetPropertyChangedSignal(\"Team\"):Connect(updateAllPlayers)\n\n----------------------------------------------------\n-- Ø3eÝe9 UI Toggle\n----------------------------------------------------\nLeftGroupBox:AddToggle('NoRenderingTeam', {\n\tText = 'No Rendering Team',\n\tTooltip = 'no rendering team',\n\tCallback = function(Value)\n\t\tNoRenderTeamEnabled = Value\n\t\tupdateAllPlayers()\n\tend\n})\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nlocal HIT_SOUND_ID = 'rbxassetid://5633695679'\nlocal HIT_SOUND_VOLUME = 4 -- C7CdC0D7C5CdC8C5 CfCe D3CcCeCbD7C0CdC8De\nlocal isHitSoundEnabled = false\n\n-- Ø3dÝ0a B2CeC3C3Cb C4CbDf C2CaCbDeD7C5CdC8Df/C2DbCaCbDeD7C5CdC8Df C7C2D3CaC0\nRightGroupBox:AddToggle('Hit Sound', {\n\tText = 'Hit Sound',\n\tTooltip = '',\n\tCallback = function(Value)\n\t\tisHitSoundEnabled = Value\n\tend\n})\n\n-- Ø3cß9aþ0f B1CbC0C9C4C5D0 C4CbDf D0C5C3D3CbC8D0CeC2CaC8 C3D0CeCcCaCeD1D2C8\nRightGroupBox:AddSlider('Hit Sound Volume', {\n\tText = 'Hit Sound Volume',\n\tDefault = HIT_SOUND_VOLUME,\n\tMin = 0,\n\tMax = 10, -- Roblox CeC3D0C0CdC8D7C8C2C0C5D2 C3D0CeCcCaCeD1D2Dc, CeC1DbD7CdCe 10  14 CcC0CaD1C8CcD3Cc\n\tRounding = 1,\n\tCompact = false,\n\tCallback = function(Value)\n\t\tHIT_SOUND_VOLUME = Value\n\tend\n})\n\n-- Ø3dÝ01 AeD1CdCeC2CdC0Df CbCeC3C8CaC0 D1D0C0C1C0D2DbC2C0CdC8Df C7C2D3CaC0 CfD0C8 C8C7CcC5CdC5CdC8C8 D3D0CeCdC0\nlocal player = game.Players.LocalPlayer\nlocal additionals = player:WaitForChild(\"Additionals\")\nlocal totalDamage = additionals:WaitForChild(\"TotalDamage\")\n\ntotalDamage.Changed:Connect(function()\n\tlocal newValue = totalDamage.Value\n\n\tif isHitSoundEnabled and newValue ~= 0 then\n\t\tlocal hitSound = Instance.new(\"Sound\")\n\t\thitSound.SoundId = HIT_SOUND_ID\n\t\thitSound.Volume = HIT_SOUND_VOLUME\n\t\thitSound.Parent = game:GetService(\"SoundService\")\n\t\thitSound:Play()\n\n\t\t-- B3C4C0CbDfC5Cc C7C2D3Ca D7C5D0C5C7 Debris\n\t\tgame:GetService(\"Debris\"):AddItem(hitSound, 3)\n\tend\nend)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n-- =============================================\n-- ========== AdA0B1B2B0AeA9AaA8 AfAe B3AcAeAbB7A0AdA8Be ===========\n-- =============================================\n\nlocal FRAME_SIZE = UDim2.new(0, 177, 0, 25)\nlocal FRAME_POSITION_Y = 0.80\nlocal FRAME_COLOR = Color3.fromRGB(20, 20, 20)\nlocal FRAME_TRANSPARENCY = 0.2\nlocal FRAME_CORNER_RADIUS = 8\n\nlocal FONT_SIZE = 13\nlocal TEXT_COLOR = Color3.fromRGB(255, 255, 255)\nlocal SYMBOL_COLOR = Color3.fromRGB(255, 255, 0)\n\n-- Ø3dÝ27 BdD2C8 CfC0D0C0CcC5D2D0Db CcCeC6CdCe C1D3C4C5D2 CcC5CdDfD2Dc D7C5D0C5C7 UI\nlocal ANIMATION_DURATION = 2 -- C4CbC8D2C5CbDcCdCeD1D2Dc C6C8C7CdC8 D5C8D2-C8CdC4C8CaC0D2CeD0C0\nlocal FADE_IN_TIME = 0.2\nlocal FADE_OUT_TIME = 1\n\n-- =============================================\n-- ============= UI AdA0B1B2B0AeA9AaA8 ===================\n-- =============================================\n\nlocal isHitLogEnabled = true\n\n-- '05 B2CeC3C3Cb C4CbDf C2CaCbDeD7C5CdC8Df/C2DbCaCbDeD7C5CdC8Df D5C8D2-C8CdC4C8CaC0D2CeD0C0\nRightGroupBox:AddToggle('Hit Log', {\n\tText = 'Hit Log',\n\tTooltip = '',\n\tCallback = function(Value)\n\t\tisHitLogEnabled = Value\n\tend\n})\n\n-- Ø3cß9aþ0f B1CbC0C9C4C5D0 C4CbDf C8C7CcC5CdC5CdC8Df C4CbC8D2C5CbDcCdCeD1D2C8 (ANIMATION_DURATION)\nRightGroupBox:AddSlider('Hit Log Duration', {\n\tText = 'Hit Log Duration',\n\tDefault = ANIMATION_DURATION,\n\tMin = 0.5,\n\tMax = 5,\n\tRounding = 1,\n\tCompact = false,\n\tCallback = function(Value)\n\t\tANIMATION_DURATION = Value\n\tend\n})\n\n-- =============================================\n-- ============== AeB1AdAeA2AdAeA9 AaAeA4 ==================\n-- =============================================\n\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Players = game:GetService(\"Players\")\n\nlocal previousDamage = 0\n\nlocal screenGui = Instance.new(\"ScreenGui\", Players.LocalPlayer:WaitForChild(\"PlayerGui\"))\nscreenGui.Name = \"HitIndicatorGui\"\nscreenGui.ResetOnSpawn = false\n\nlocal function createHitIndicator(damageAmount)\n\tif not isHitLogEnabled then return end\n\n\t-- 1. B1CeC7C4C0C5Cc CeD1CdCeC2CdD3De D0C0CcCaD3\n\tlocal frame = Instance.new(\"Frame\")\n\tframe.Size = FRAME_SIZE\n\tframe.Position = UDim2.new(0.5, 0, FRAME_POSITION_Y, 0)\n\tframe.AnchorPoint = Vector2.new(0.5, 0.5)\n\tframe.BackgroundColor3 = FRAME_COLOR\n\tframe.BackgroundTransparency = 1\n\tframe.BorderSizePixel = 0\n\tframe.Parent = screenGui\n\n\tlocal uiCorner = Instance.new(\"UICorner\", frame)\n\tuiCorner.CornerRadius = UDim.new(0, FRAME_CORNER_RADIUS)\n\n\t-- 2. Layout\n\tlocal listLayout = Instance.new(\"UIListLayout\", frame)\n\tlistLayout.FillDirection = Enum.FillDirection.Horizontal\n\tlistLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n\tlistLayout.VerticalAlignment = Enum.VerticalAlignment.Center\n\tlistLayout.Padding = UDim.new(0, 8)\n\n\t-- 3. B1C8CcC2CeCb &a0\n\tlocal symbolLabel = Instance.new(\"TextLabel\", frame)\n\tsymbolLabel.Size = UDim2.new(0, FONT_SIZE, 1, 0)\n\tsymbolLabel.BackgroundTransparency = 1\n\tsymbolLabel.Font = Enum.Font.SourceSansBold\n\tsymbolLabel.Text = \"&a0\"\n\tsymbolLabel.TextSize = FONT_SIZE\n\tsymbolLabel.TextColor3 = SYMBOL_COLOR\n\tsymbolLabel.TextTransparency = 1\n\n\t-- 4. B2C5CaD1D2 D1 D3D0CeCdCeCc\n\tlocal infoLabel = Instance.new(\"TextLabel\", frame)\n\tinfoLabel.Size = UDim2.new(0, 150, 1, 0)\n\tinfoLabel.BackgroundTransparency = 1\n\tinfoLabel.Font = Enum.Font.SourceSansSemibold\n\tinfoLabel.TextSize = FONT_SIZE\n\tinfoLabel.TextColor3 = TEXT_COLOR\n\tinfoLabel.TextXAlignment = Enum.TextXAlignment.Left\n\tinfoLabel.TextTransparency = 1\n\tinfoLabel.Text = string.format(\"HIT | DAMAGE: %d\", math.floor(damageAmount))\n\n\t-- 5. A0CdC8CcC0D6C8Df CfCeDfC2CbC5CdC8Df C8 C8D1D7C5C7CdCeC2C5CdC8Df\n\tlocal fadeInInfo = TweenInfo.new(FADE_IN_TIME, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)\n\tlocal fadeOutInfo = TweenInfo.new(FADE_OUT_TIME, Enum.EasingStyle.Sine, Enum.EasingDirection.In)\n\n\t-- AfCeDfC2CbC5CdC8C5\n\tTweenService:Create(frame, fadeInInfo, { BackgroundTransparency = FRAME_TRANSPARENCY }):Play()\n\tTweenService:Create(symbolLabel, fadeInInfo, { TextTransparency = 0 }):Play()\n\tTweenService:Create(infoLabel, fadeInInfo, { TextTransparency = 0 }):Play()\n\n\ttask.wait(ANIMATION_DURATION - FADE_OUT_TIME)\n\n\t-- A8D1D7C5C7CdCeC2C5CdC8C5\n\tlocal fadeOutFrameTween = TweenService:Create(frame, fadeOutInfo, { BackgroundTransparency = 1 })\n\tTweenService:Create(symbolLabel, fadeOutInfo, { TextTransparency = 1 }):Play()\n\tTweenService:Create(infoLabel, fadeOutInfo, { TextTransparency = 1 }):Play()\n\tfadeOutFrameTween:Play()\n\n\tfadeOutFrameTween.Completed:Connect(function()\n\t\tframe:Destroy()\n\tend)\nend\n\n-- B1CbC5C4C8Cc C7C0 C8C7CcC5CdC5CdC8C5Cc CeC1D9C5C3Ce D3D0CeCdC0\nlocal player = Players.LocalPlayer\nlocal additionals = player:WaitForChild(\"Additionals\")\nlocal totalDamage = additionals:WaitForChild(\"TotalDamage\")\n\ntotalDamage.Changed:Connect(function()\n\tlocal newValue = totalDamage.Value\n\tlocal damageDealt = newValue - previousDamage\n\tif damageDealt > 0 then\n\t\tcreateHitIndicator(damageDealt)\n\tend\n\tpreviousDamage = newValue\nend)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nlocal Camera = workspace.CurrentCamera\nlocal RunService = game:GetService(\"RunService\")\n\n-- AdC0D1D2D0CeC9CaC8\nlocal DefaultFOV = 70\nlocal CurrentFOV = DefaultFOV\nlocal FOVEnabled = false\nlocal FOVConnection = nil\n\nCamera.FieldOfView = DefaultFOV\n\n-- '05 B4D3CdCaD6C8Df C2CaCbDeD7C5CdC8Df/C2DbCaCbDeD7C5CdC8Df\nlocal function ToggleFOV(enabled)\n\tFOVEnabled = enabled\n\n\tif enabled then\n\t\tif FOVConnection then\n\t\t\tFOVConnection:Disconnect()\n\t\tend\n\n\t\tFOVConnection = RunService.RenderStepped:Connect(function()\n\t\t\tCamera.FieldOfView = CurrentFOV\n\t\tend)\n\telse\n\t\tif FOVConnection then\n\t\t\tFOVConnection:Disconnect()\n\t\t\tFOVConnection = nil\n\t\tend\n\t\tCamera.FieldOfView = DefaultFOV -- D1C1D0CeD1 CfD0C8 C2DbCaCbDeD7C5CdC8C8\n\tend\nend\n\n-- '05 B4D3CdCaD6C8Df C8C7CcC5CdC5CdC8Df C7CdC0D7C5CdC8Df FOV\nlocal function UpdateFOV(Value)\n\tCurrentFOV = Value\n\tif FOVEnabled then\n\t\tCamera.FieldOfView = Value\n\tend\nend\n\n-- Ø3cß9b A4CeC1C0C2CbDfC5Cc UI D1CbC5C2C0\nRightGroupBox:AddToggle('FOVEnabled', {\n\tText = 'FOV Changer',\n\tTooltip = 'Enable or disable FOV changer',\n\tCallback = function(Value)\n\t\tToggleFOV(Value)\n\tend\n})\n\nRightGroupBox:AddSlider('FOVValue', {\n\tText = 'FOV Value',\n\tDefault = DefaultFOV,\n\tMin = 30,\n\tMax = 120,\n\tRounding = 0,\n\tTooltip = 'Change your field of view',\n\tCallback = function(Value)\n\t\tUpdateFOV(Value)\n\tend\n})\n\n\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal player = Players.LocalPlayer\nlocal camera = Workspace.CurrentCamera\nlocal CAMERA_DISTANCE = 12\nlocal thirdPersonEnabled = false\nlocal currentHumanoid = nil\n\n-- CeD7C8D1D2CaC0 CfD0C5C4DbC4D3D9C8D5 CfCeC4CaCbDeD7C5CdC8C9\nif _G.ThirdPersonConnections then\n    for _, conn in pairs(_G.ThirdPersonConnections) do\n        conn:Disconnect()\n    end\nend\n_G.ThirdPersonConnections = {}\n\n-- D4D3CdCaD6C8Df CfD0C8C2DfC7CaC8 CaC0CcC5D0Db Ca CfC5D0D1CeCdC0C6D3\nlocal function bindHumanoid(humanoid)\n    if not humanoid then return end\n    currentHumanoid = humanoid\n\n    pcall(function()\n        humanoid.Died:Connect(function()\n            currentHumanoid = nil\n        end)\n    end)\n\n    camera = Workspace.CurrentCamera or camera\n    if camera then\n        camera.CameraType = Enum.CameraType.Custom\n        camera.CameraSubject = currentHumanoid\n    end\n\n    player.CameraMinZoomDistance = CAMERA_DISTANCE\n    player.CameraMaxZoomDistance = CAMERA_DISTANCE\nend\n\n-- CeC1D0C0C1CeD2CaC0 C4CeC1C0C2CbC5CdC8Df CfC5D0D1CeCdC0C6C0\nlocal function onCharacterAdded(character)\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\") or character:WaitForChild(\"Humanoid\", 5)\n    if humanoid then\n        bindHumanoid(humanoid)\n    end\nend\n\n-- '05 C4CeC1C0C2CbDfC5Cc UI-D2CeC3C3Cb C8 D1CbC0C9C4C5D0\nRightGroupBox:AddToggle(\"ThirdPersonToggle\", {\n    Text = \"Third Person\",\n    Tooltip = \"third person\",\n    Default = false,\n    Callback = function(Value)\n        thirdPersonEnabled = Value\n\n        if thirdPersonEnabled then\n            -- C2CaCbDeD7C0C5Cc 3-C5 CbC8D6Ce\n            player.CharacterAdded:Connect(onCharacterAdded)\n            if player.Character then\n                onCharacterAdded(player.Character)\n            end\n\n            table.insert(_G.ThirdPersonConnections, Workspace:GetPropertyChangedSignal(\"CurrentCamera\"):Connect(function()\n                camera = Workspace.CurrentCamera\n                if currentHumanoid and camera then\n                    camera.CameraType = Enum.CameraType.Custom\n                    camera.CameraSubject = currentHumanoid\n                end\n            end))\n\n            table.insert(_G.ThirdPersonConnections, RunService.RenderStepped:Connect(function()\n                if not thirdPersonEnabled then return end\n                camera = Workspace.CurrentCamera or camera\n\n                if player.CameraMinZoomDistance ~= CAMERA_DISTANCE then\n                    player.CameraMinZoomDistance = CAMERA_DISTANCE\n                end\n                if player.CameraMaxZoomDistance ~= CAMERA_DISTANCE then\n                    player.CameraMaxZoomDistance = CAMERA_DISTANCE\n                end\n\n                if currentHumanoid and camera then\n                    if camera.CameraSubject ~= currentHumanoid then\n                        camera.CameraSubject = currentHumanoid\n                    end\n                    if camera.CameraType ~= Enum.CameraType.Custom then\n                        camera.CameraType = Enum.CameraType.Custom\n                    end\n                end\n            end))\n        else\n            -- CeD2CaCbDeD7C0C5Cc 3-C5 CbC8D6Ce\n            if camera then\n                camera.CameraType = Enum.CameraType.Custom\n                camera.CameraSubject = player.Character and player.Character:FindFirstChildOfClass(\"Humanoid\") or nil\n            end\n            player.CameraMinZoomDistance = 0.5\n            player.CameraMaxZoomDistance = 10\n            for _, conn in pairs(_G.ThirdPersonConnections) do\n                conn:Disconnect()\n            end\n            _G.ThirdPersonConnections = {}\n        end\n    end\n})\n\nRightGroupBox:AddSlider(\"ThirdPersonDistance\", {\n    Text = \"Camera Distance\",\n    Default = 12,\n    Min = 5,\n    Max = 25,\n    Rounding = 1,\n    Compact = false,\n    Callback = function(Value)\n        CAMERA_DISTANCE = Value\n        if thirdPersonEnabled then\n            player.CameraMinZoomDistance = CAMERA_DISTANCE\n            player.CameraMaxZoomDistance = CAMERA_DISTANCE\n        end\n    end\n})\n\n\n\n\n\n-- AbCeCaC0CbDcCdDbC5 CfC5D0C5CcC5CdCdDbC5\nlocal RunService = game:GetService(\"RunService\")\nlocal player = game.Players.LocalPlayer\n\n-- A3CbCeC1C0CbDcCdDbC5 CfC5D0C5CcC5CdCdDbC5\n_G.GunsChams = false\n_G.ChamsColor = Color3.fromRGB(200,200,200)\nlocal R, G, B = 200, 200, 200 -- CdC0D7C0CbDcCdDbC5 C7CdC0D7C5CdC8Df C4CbDf D1CbC0C9C4C5D0CeC2\n\n-- =====================\n-- UI: Toggle Gun Chams\n-- =====================\nRightGroupBox:AddToggle(\"GunChamsToggle\", {\n    Text = \"Gun Chams\",\n    Tooltip = \"Enable/Disable gun chams\",\n    Default = false,\n    Callback = function(Value)\n        _G.GunsChams = Value\n    end\n})\n\n-- =====================\n-- UI: RGB B1CbC0C9C4C5D0Db C4CbDf ChamsColor\n-- =====================\nRightGroupBox:AddSlider('Chams_R', {\n    Text = 'Red',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        R = Value\n        _G.ChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\nRightGroupBox:AddSlider('Chams_G', {\n    Text = 'Green',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        G = Value\n        _G.ChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\nRightGroupBox:AddSlider('Chams_B', {\n    Text = 'Blue',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        B = Value\n        _G.ChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\n-- =====================\n-- RenderStepped C4CbDf Gun Chams\n-- =====================\nRunService.RenderStepped:Connect(function()\n    for _, Stuff in ipairs(workspace.Camera:GetChildren()) do\n        if Stuff:IsA(\"Model\") and Stuff.Name == \"Arms\" then\n            for _, Part in ipairs(Stuff:GetChildren()) do\n                if Part:IsA(\"MeshPart\") or Part:IsA(\"BasePart\") then\n                    if _G.GunsChams then\n                        Part.Color = _G.ChamsColor\n                        Part.Material = Enum.Material.ForceField\n                    else\n                        Part.Color = Color3.fromRGB(200,200,200)\n                        Part.Material = Enum.Material.Plastic\n                    end\n                end\n            end\n        end\n    end\n    task.wait()\nend)\n\n\n\n\nlocal RunService = game:GetService(\"RunService\")\nlocal player = game.Players.LocalPlayer\n\n-- A3CbCeC1C0CbDcCdDbC5 CfC5D0C5CcC5CdCdDbC5\n_G.ArmsChams = false\nlocal R, G, B = 200, 200, 200\n_G.ArmsChamsColor = Color3.fromRGB(R, G, B)\n\n-- UI Toggle\nRightGroupBox:AddToggle(\"ArmChamsToggle\", {\n    Text = \"Arm Chams\",\n    Tooltip = \"Enable/Disable arm chams\",\n    Default = false,\n    Callback = function(Value)\n        _G.ArmsChams = Value\n    end\n})\n\n-- RGB B1CbC0C9C4C5D0Db\nRightGroupBox:AddSlider('ArmChams_R', {\n    Text = 'Red',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        R = Value\n        _G.ArmsChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\nRightGroupBox:AddSlider('ArmChams_G', {\n    Text = 'Green',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        G = Value\n        _G.ArmsChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\nRightGroupBox:AddSlider('ArmChams_B', {\n    Text = 'Blue',\n    Default = 200,\n    Min = 0,\n    Max = 255,\n    Rounding = 0,\n    Callback = function(Value)\n        B = Value\n        _G.ArmsChamsColor = Color3.fromRGB(R, G, B)\n    end\n})\n\n-- RenderStepped\nRunService.RenderStepped:Connect(function()\n    for _, Stuff in ipairs(workspace.Camera:GetChildren()) do\n        if Stuff:IsA(\"Model\") and Stuff.Name == \"Arms\" then\n            for _, AnotherStuff in ipairs(Stuff:GetChildren()) do\n                if AnotherStuff:IsA(\"Model\") and AnotherStuff.Name ~= \"AnimSaves\" then\n                    for _, Arm in ipairs(AnotherStuff:GetChildren()) do\n                        if Arm:IsA(\"BasePart\") then\n                            if _G.ArmsChams then\n                                -- C4C5CbC0C5Cc CfD0CeC7D0C0D7CdCeD1D2Dc CcC5CdDcD8C5, D7D2CeC1Db D6C2C5D2 C1DbCb C2C8C4C5Cd\n                                Arm.Transparency = 0.5\n                                Arm.Material = Enum.Material.ForceField\n                                Arm.Color = _G.ArmsChamsColor\n                                -- CeCaD0C0D8C8C2C0C5Cc C2D1C5 C4CeD7C5D0CdC8C5 D7C0D1D2C8 D2CeC6C5\n                                for _, Part in ipairs(Arm:GetChildren()) do\n                                    if Part:IsA(\"BasePart\") then\n                                        Part.Material = Enum.Material.ForceField\n                                        Part.Color = _G.ArmsChamsColor\n                                        Part.Transparency = 0.5\n                                    end\n                                end\n                            else\n                                Arm.Transparency = 0\n                                Arm.Material = Enum.Material.Plastic\n                                Arm.Color = Color3.fromRGB(200,200,200)\n                                for _, Part in ipairs(Arm:GetChildren()) do\n                                    if Part:IsA(\"BasePart\") then\n                                        Part.Material = Enum.Material.Plastic\n                                        Part.Color = Color3.fromRGB(200,200,200)\n                                        Part.Transparency = 0\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    task.wait()\nend)\n\n\n\nlocal RightGroupBox = Tabs.Visuals:AddRightGroupbox('Ambient')\n\n\n\n\n--// Ambient Visual System: Time, Fog, Brightness, Saturation, RGB Control (All Right Side)\n-- Made with love Ø3dÜ9c\n\nlocal Lighting = game:GetService(\"Lighting\")\nlocal TweenService = game:GetService(\"TweenService\")\n\n-- Check or create ColorCorrectionEffect\nlocal colorEffect = Lighting:FindFirstChild(\"WorldColorEffect\")\nif not colorEffect then\n\tcolorEffect = Instance.new(\"ColorCorrectionEffect\")\n\tcolorEffect.Name = \"WorldColorEffect\"\n\tcolorEffect.Parent = Lighting\nend\n\n-- Config\nlocal CONFIG = {\n\tAmbientColor1 = Color3.fromRGB(140, 0, 255),\n\tAmbientColor2 = Color3.fromRGB(90, 0, 180),\n\tOutdoorAmbient = Color3.fromRGB(100, 0, 160),\n\tBrightness = 1.2,\n\tFogColor = Color3.fromRGB(120, 0, 180),\n\tFogStart = 0,\n\tFogEnd = 10000, -- increased max fog distance\n\tPulseTime = 6,\n\tTransitionTime = 1.0,\n\tSaturation = 0.2,\n}\n\nlocal AmbientEnabled = false\nlocal PulseLoop = nil\nlocal CurrentFogEnd = CONFIG.FogEnd\nlocal CurrentBrightness = CONFIG.Brightness\nlocal CurrentSaturation = CONFIG.Saturation\nlocal FogR, FogG, FogB = CONFIG.FogColor.R * 255, CONFIG.FogColor.G * 255, CONFIG.FogColor.B * 255\n\n-- === Functions ===\n\nlocal function UpdateFogColor()\n\tlocal color = Color3.fromRGB(FogR, FogG, FogB)\n\tTweenService:Create(Lighting, TweenInfo.new(0.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {\n\t\tFogColor = color\n\t}):Play()\nend\n\nlocal function EnableAmbient()\n\tAmbientEnabled = true\n\tTweenService:Create(Lighting, TweenInfo.new(CONFIG.TransitionTime), {\n\t\tAmbient = CONFIG.AmbientColor1,\n\t\tOutdoorAmbient = CONFIG.OutdoorAmbient,\n\t\tBrightness = CurrentBrightness,\n\t\tFogColor = Color3.fromRGB(FogR, FogG, FogB),\n\t\tFogStart = CONFIG.FogStart,\n\t\tFogEnd = CurrentFogEnd,\n\t}):Play()\n\n\tTweenService:Create(colorEffect, TweenInfo.new(1), {\n\t\tSaturation = CurrentSaturation\n\t}):Play()\n\n\tPulseLoop = task.spawn(function()\n\t\twhile AmbientEnabled do\n\t\t\tlocal t1 = TweenService:Create(Lighting, TweenInfo.new(CONFIG.PulseTime, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { Ambient = CONFIG.AmbientColor2 })\n\t\t\tt1:Play()\n\t\t\tt1.Completed:Wait()\n\t\t\tif not AmbientEnabled then break end\n\t\t\tlocal t2 = TweenService:Create(Lighting, TweenInfo.new(CONFIG.PulseTime, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { Ambient = CONFIG.AmbientColor1 })\n\t\t\tt2:Play()\n\t\t\tt2.Completed:Wait()\n\t\tend\n\tend)\nend\n\nlocal function DisableAmbient()\n\tAmbientEnabled = false\n\tTweenService:Create(Lighting, TweenInfo.new(CONFIG.TransitionTime), {\n\t\tAmbient = Color3.fromRGB(128,128,128),\n\t\tOutdoorAmbient = Color3.fromRGB(128,128,128),\n\t\tBrightness = 1,\n\t\tFogColor = Color3.fromRGB(200,200,200),\n\t\tFogStart = 0,\n\t\tFogEnd = 10000,\n\t}):Play()\n\tTweenService:Create(colorEffect, TweenInfo.new(1), { Saturation = 0 }):Play()\nend\n\n-- === UI ===\n\n-- Ø3dÝ18 Ambient Toggle\nRightGroupBox:AddToggle('Ambient', {\n\tText = 'Ambient',\n\tTooltip = 'Enables or disables the purple world effect.',\n\tCallback = function(state)\n\t\tif state then\n\t\t\tEnableAmbient()\n\t\telse\n\t\t\tDisableAmbient()\n\t\tend\n\tend\n})\n\n-- Ø3cß07 Time\nRightGroupBox:AddSlider('Time', {\n\tText = 'Time of Day',\n\tDefault = 12,\n\tMin = 0,\n\tMax = 24,\n\tRounding = 1,\n\tTooltip = 'Changes the in-game time (0 = Night, 12 = Day, 18 = Sunset).',\n\tCallback = function(value)\n\t\tTweenService:Create(Lighting, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {\n\t\t\tClockTime = value\n\t\t}):Play()\n\tend\n})\n\n-- Ø3cß2b Fog Distance\nRightGroupBox:AddSlider('FogEnd', {\n\tText = 'Fog Distance',\n\tDefault = CONFIG.FogEnd,\n\tMin = 50,\n\tMax = 10000,\n\tRounding = 0,\n\tTooltip = 'Controls how far the fog extends (lower = thicker fog).',\n\tCallback = function(value)\n\t\tCurrentFogEnd = value\n\t\tTweenService:Create(Lighting, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {\n\t\t\tFogEnd = value\n\t\t}):Play()\n\tend\n})\n\n-- Ø3dÜa1 Brightness\nRightGroupBox:AddSlider('Brightness', {\n\tText = 'Brightness',\n\tDefault = CONFIG.Brightness,\n\tMin = 0,\n\tMax = 3,\n\tRounding = 1,\n\tTooltip = 'Adjusts overall world brightness.',\n\tCallback = function(value)\n\t\tCurrentBrightness = value\n\t\tTweenService:Create(Lighting, TweenInfo.new(0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {\n\t\t\tBrightness = value\n\t\t}):Play()\n\tend\n})\n\n-- Ø3cßa8 Saturation\nRightGroupBox:AddSlider('Saturation', {\n\tText = 'Saturation',\n\tDefault = CONFIG.Saturation,\n\tMin = -1,\n\tMax = 1,\n\tRounding = 2,\n\tTooltip = 'Controls color saturation (-1 = grayscale, +1 = vivid colors).',\n\tCallback = function(value)\n\t\tCurrentSaturation = value\n\t\tTweenService:Create(colorEffect, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {\n\t\t\tSaturation = value\n\t\t}):Play()\n\tend\n})\n\n-- Ø3cß08 Fog Color RGB Sliders\nRightGroupBox:AddSlider('FogR', {\n\tText = 'Fog Red',\n\tDefault = FogR,\n\tMin = 0,\n\tMax = 255,\n\tRounding = 0,\n\tTooltip = 'Adjust the red component of the fog color.',\n\tCallback = function(value)\n\t\tFogR = value\n\t\tUpdateFogColor()\n\tend\n})\n\nRightGroupBox:AddSlider('FogG', {\n\tText = 'Fog Green',\n\tDefault = FogG,\n\tMin = 0,\n\tMax = 255,\n\tRounding = 0,\n\tTooltip = 'Adjust the green component of the fog color.',\n\tCallback = function(value)\n\t\tFogG = value\n\t\tUpdateFogColor()\n\tend\n})\n\nRightGroupBox:AddSlider('FogB', {\n\tText = 'Fog Blue',\n\tDefault = FogB,\n\tMin = 0,\n\tMax = 255,\n\tRounding = 0,\n\tTooltip = 'Adjust the blue component of the fog color.',\n\tCallback = function(value)\n\t\tFogB = value\n\t\tUpdateFogColor()\n\tend\n})\n\n\n\n\n\n\n\n\n\nlocal LeftGroupBox = Tabs.Aim:AddLeftGroupbox('Aimbot')\n\n\n\nlocal Players = game:GetService(\"Players\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal camera = workspace.CurrentCamera\nlocal Drawing = Drawing or nil -- D7D2CeC1Db CdC5 CaD0C0D8C8CbCe, C5D1CbC8 Drawing API CdC5D2\n\nlocal localPlayer = Players.LocalPlayer\nlocal holdingMouse = false\n\n-- ================= AdC0D1D2D0CeC9CaC8 =================\nlocal UseTeamCheck = true\n_G.SilentAimEnabled = false\n_G.FovValue = 100 -- D0C0C4C8D3D1 C2 CfC8CaD1C5CbDfD5\n_G.ShowFovCircle = false\n\n-- ================= AbAaAc =================\nUserInputService.InputBegan:Connect(function(input, processed)\n\tif processed then return end\n\tif input.UserInputType == Enum.UserInputType.MouseButton1 then\n\t\tholdingMouse = true\n\tend\nend)\n\nUserInputService.InputEnded:Connect(function(input)\n\tif input.UserInputType == Enum.UserInputType.MouseButton1 then\n\t\tholdingMouse = false\n\tend\nend)\n\n-- ================= B4D3CdCaD6C8Df CfCeC8D1CaC0 C1CbC8C6C0C9D8C5C3Ce Ca CfD0C8D6C5CbD3 =================\nlocal function getClosestToCrosshair()\n\tlocal nearest = nil\n\tlocal shortestScreenDist = math.huge\n\tlocal mousePos = UserInputService:GetMouseLocation()\n\tlocal fov = _G.FovValue or 100\n\n\tfor _, pl in ipairs(Players:GetPlayers()) do\n\t\tif pl ~= localPlayer and pl.Character and pl.Character.Parent then\n\t\t\tlocal humanoid = pl.Character:FindFirstChildOfClass(\"Humanoid\")\n\t\t\tlocal head = pl.Character:FindFirstChild(\"Head\")\n\n\t\t\tif head and humanoid and humanoid.Health > 0 then\n\t\t\t\tif UseTeamCheck and localPlayer.Team and pl.Team and pl.Team == localPlayer.Team then\n\t\t\t\t\tcontinue\n\t\t\t\tend\n\n\t\t\t\tlocal headPos, onScreen = camera:WorldToViewportPoint(head.Position)\n\t\t\t\tif onScreen then\n\t\t\t\t\tlocal dist = (Vector2.new(headPos.X, headPos.Y) - mousePos).Magnitude\n\t\t\t\t\tif dist <= fov then\n\t\t\t\t\t\tif dist < shortestScreenDist then\n\t\t\t\t\t\t\tshortestScreenDist = dist\n\t\t\t\t\t\t\tnearest = head\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\treturn nearest\nend\n\n-- ================= B0C8D1CeC2C0CdC8C5 FOV CaD0D3C3C0 =================\nlocal fovCircle = Drawing and Drawing.new(\"Circle\") or nil\n\nif fovCircle then\n\tfovCircle.Color = Color3.fromRGB(255, 255, 255)\n\tfovCircle.Thickness = 1.5\n\tfovCircle.Filled = false\n\tfovCircle.Transparency = 0.8\nend\n\nRunService.RenderStepped:Connect(function()\n\tlocal mousePos = UserInputService:GetMouseLocation()\n\n\tif fovCircle then\n\t\tfovCircle.Visible = _G.ShowFovCircle\n\t\tfovCircle.Position = mousePos\n\t\tfovCircle.Radius = _G.FovValue or 100\n\tend\n\n\tif holdingMouse and _G.SilentAimEnabled then\n\t\tlocal target = getClosestToCrosshair()\n\t\tif target then\n\t\t\tlocal originalCFrame = camera.CFrame\n\t\t\tcamera.CFrame = CFrame.new(originalCFrame.Position, target.Position)\n\t\t\ttask.defer(function()\n\t\t\t\tcamera.CFrame = originalCFrame\n\t\t\tend)\n\t\tend\n\tend\nend)\n\n-- ================= UI BdCbC5CcC5CdD2Db =================\n\n-- AfC5D0C5CaCbDeD7C0D2C5CbDc Silent Aim\nLeftGroupBox:AddToggle('Silent Aim', { \n\tText = 'Silent Aim', \n\tDefault = false,\n\tCallback = function(Value)\n\t\t_G.SilentAimEnabled = Value\n\tend\n})\n\n-- B1CbC0C9C4C5D0 FOV\nLeftGroupBox:AddSlider('Fov Slider', { \n\tText = 'Fov (pixels)', \n\tDefault = 100,\n\tMin = 0,\n\tMax = 750,\n\tRounding = 1,\n\tCompact = false,\n\tCallback = function(Value)\n\t\t_G.FovValue = Value\n\tend\n})\n\n-- B2CeC3C3Cb C4CbDf CaD0D3C3C0 FOV\nLeftGroupBox:AddToggle('Show Fov Circle', { \n\tText = 'Show FOV Circle', \n\tDefault = false,\n\tTooltip = 'Show Fov circle',\n\tCallback = function(Value)\n\t\t_G.ShowFovCircle = Value\n\tend\n})\n\n\n\n\n\n\n\n\n-- A8CdC8D6C8C0CbC8C7C0D6C8Df\nif _G.aimlock == nil then\n    _G.aimlock = false\nend\n\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Camera = workspace.CurrentCamera\n\nlocal cursorLocked = false\nlocal targetPlayer = nil\nlocal targetHead = nil\nlocal smoothness = 0.1\nlocal fovSize = 200 -- B0C0C4C8D3D1 CaD0D3C3C0 (CfCe D3CcCeCbD7C0CdC8De)\nlocal fovCircle\n\n-- B1CeC7C4C0E1Cc C2C8C7D3C0CbDcCdDbC9 FOV CaD0D3C3 (Drawing API)\nfovCircle = Drawing.new(\"Circle\")\nfovCircle.Radius = fovSize\nfovCircle.Thickness = 2\nfovCircle.Filled = false\nfovCircle.Color = Color3.fromRGB(255, 255, 255)\nfovCircle.Transparency = 1\nfovCircle.Visible = false -- AfCe D3CcCeCbD7C0CdC8De D1CaD0DbD2\n\n-- AeC1CdCeC2CbDfC5Cc CfCeC7C8D6C8De FOV CaD0D3C3C0 CdC0 DdCaD0C0CdC5\nRunService.RenderStepped:Connect(function()\n    if fovCircle.Visible then\n        local mousePos = UserInputService:GetMouseLocation()\n        fovCircle.Position = Vector2.new(mousePos.X, mousePos.Y + 36)\n    end\nend)\n\n-- AfD0CeC2C5D0CaC0 D1CeD1D2CeDfCdC8Df C8C3D0CeCaC0\nlocal function IsPlayerKnockedOrGrabbed(player)\n    local character = player.Character\n    if character then\n        local bodyEffects = character:FindFirstChild(\"BodyEffects\")\n        local grabbingConstraint = character:FindFirstChild(\"GRABBING_CONSTRAINT\")\n        if (bodyEffects and bodyEffects:FindFirstChild(\"K.O\") and bodyEffects[\"K.O\"].Value) or grabbingConstraint then\n            return true\n        end\n    end\n    return false\nend\n\n-- AfCeC8D1Ca C1CbC8C6C0C9D8C5C9 C3CeCbCeC2Db C2 CfD0C5C4C5CbC0D5 FOV\nlocal function FindClosestPlayerHead()\n    local closestPlayer = nil\n    local closestDistance = math.huge\n    local mousePosition = Vector2.new(UserInputService:GetMouseLocation().X, UserInputService:GetMouseLocation().Y)\n\n    for _, player in pairs(Players:GetPlayers()) do\n        if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild(\"Head\") then\n            if player.Team == LocalPlayer.Team then\n                continue -- B2C8Cc-D7C5Ca\n            end\n\n            local character = player.Character\n            local humanoid = character:FindFirstChild(\"Humanoid\")\n\n            if humanoid and humanoid.Health > 0 then\n                if IsPlayerKnockedOrGrabbed(player) then continue end\n\n                local head = character.Head\n                local screenPoint, onScreen = Camera:WorldToScreenPoint(head.Position)\n                if onScreen then\n                    local distance = (mousePosition - Vector2.new(screenPoint.X, screenPoint.Y)).Magnitude\n\n                    -- AfD0CeC2C5D0DfC5Cc, CdC0D5CeC4C8D2D1Df CbC8 C8C3D0CeCa C2 CfD0C5C4C5CbC0D5 CaD0D3C3C0\n                    if distance <= fovSize and distance < closestDistance then\n                        closestDistance = distance\n                        closestPlayer = player\n                    end\n                end\n            end\n        end\n    end\n\n    if closestPlayer then\n        return closestPlayer.Character.Head, closestPlayer\n    end\n    return nil, nil\nend\n\n-- Lock/Unlock CaD3D0D1CeD0C0\nlocal function LockCursorToHead()\n    targetHead, targetPlayer = FindClosestPlayerHead()\n    if targetHead then\n        cursorLocked = true\n        UserInputService.MouseIconEnabled = false\n    end\nend\n\nlocal function UnlockCursor()\n    UserInputService.MouseIconEnabled = true\n    targetHead = nil\n    targetPlayer = nil\n    cursorLocked = false\nend\n\n-- Toggle Aimlock\nLeftGroupBox:AddToggle('Aimlock', {\n    Text = 'Aimlock',\n    Default = false,\n    Tooltip = 'Locks your aim onto player heads',\n    Callback = function(Value)\n        _G.aimlock = Value\n        cursorLocked = false\n        fovCircle.Visible = Value -- AfCeCaC0C7C0D2Dc/D1CaD0DbD2Dc FOV CaD0D3C3 CfD0C8 C2CaCbDeD7C5CdC8C8 Aimlock\n    end\n})\n\n-- KeyPicker C4CbDf Aimlock\nLeftGroupBox:AddLabel('Keybind'):AddKeyPicker('AimlockKey', {\n    Default = 'MB2', \n    SyncToggleState = false,\n    Mode = 'Toggle',\n    Text = 'Aimlock Key',\n    NoUI = false\n})\n\nlocal AimlockKey = Options.AimlockKey\n\n-- B1CbC0C9C4C5D0 CfCbC0C2CdCeD1D2C8 (0 = D0C5C7CaC8C9, 10 = CfCbC0C2CdDbC9)\nLeftGroupBox:AddSlider('SmoothnessSlider', {\n    Text = 'Aimlock Smoothness',\n    Default = 5,\n    Min = 0,\n    Max = 10,\n    Rounding = 1,\n    Compact = false,\n\n    Callback = function(Value)\n        -- B7C5Cc C1CeCbDcD8C5 C7CdC0D7C5CdC8C5, D2C5Cc CcC5CdDcD8C5 D1CaCeD0CeD1D2Dc CfCeC2CeD0CeD2C0 CaC0CcC5D0Db (C1CeCbC5C5 CfCbC0C2CdCe)\n        smoothness = math.clamp(Value, 0, 10)\n        print('[cb] Aimlock smoothness changed! New value:', smoothness)\n    end,\n\n    Tooltip = '0 = instant, 10 = very smooth aimlock', \n    Disabled = false, \n    Visible = true, \n})\n\n-- AeD1CdCeC2CdCeC9 D6C8CaCb CdC0C2C5C4C5CdC8Df\nRunService.RenderStepped:Connect(function()\n    if cursorLocked and _G.aimlock and targetHead and targetPlayer then\n        if IsPlayerKnockedOrGrabbed(targetPlayer) then\n            UnlockCursor()\n        else\n            -- B7C5Cc C2DbD8C5 smoothness, D2C5Cc CcC5CdDcD8C5 D1CaCeD0CeD1D2Dc (C5D9E1 CfCbC0C2CdC5C5)\n            local t = 1 / (1 + (smoothness * 10)) -- Ø3dÝ25 B1D3CfC5D0 CfCbC0C2CdC0Df D4CeD0CcD3CbC0\n            t = math.clamp(t, 0.01, 1)\n\n            Camera.CFrame = Camera.CFrame:Lerp(\n                CFrame.new(Camera.CFrame.Position, targetHead.Position),\n                t\n            )\n        end\n    end\nend)\n\n\n\n-- B1CbC0C9C4C5D0 D0C0C7CcC5D0C0 FOV CaD0D3C3C0\nLeftGroupBox:AddSlider('FOVSlider', {\n    Text = 'FOV Size',\n    Default = 200,\n    Min = 50,\n    Max = 500,\n    Rounding = 1,\n    Compact = false,\n\n    Callback = function(Value)\n        fovSize = Value\n        fovCircle.Radius = fovSize\n        print('[cb] FOV size changed:', Value)\n    end,\n\n    Tooltip = 'Adjust the aimlock FOV radius', \n    Disabled = false, \n    Visible = true, \n})\n\n-- B6C8CaCb CfD0CeC2C5D0CaC8 CaCbC0C2C8D8C8 Aimlock\ntask.spawn(function()\n    while true do\n        task.wait()\n        if Library.Unloaded then break end\n\n        local state = AimlockKey:GetState()\n        if state then\n            if not cursorLocked and _G.aimlock then\n                LockCursorToHead()\n            end\n        else\n            if cursorLocked then\n                UnlockCursor()\n            end\n        end\n    end\nend)\n\n-- AeD1CdCeC2CdCeC9 D6C8CaCb CdC0C2C5C4C5CdC8Df\nRunService.RenderStepped:Connect(function()\n    if cursorLocked and _G.aimlock and targetHead and targetPlayer then\n        if IsPlayerKnockedOrGrabbed(targetPlayer) then\n            UnlockCursor()\n        else\n            local alpha = 1 - smoothness\n            alpha = math.max(alpha, 0.01)\n            Camera.CFrame = Camera.CFrame:Lerp(CFrame.new(Camera.CFrame.Position, targetHead.Position), alpha)\n        end\n    end\nend)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nLeftGroupBox:AddToggle('Triggerbot', {\n\tText = 'triggerbot',\n\tTooltip = 'trigger bot', \n\tDisabledTooltip = 'trigger bot', \n\tCallback = function(Value)\n\t\t        if Value then\n            -- C2CaCbDeD7C0C5Cc C0C2D2Ce-D1D2D0C5CbDcC1D3\n            _G.AutoFire = true\n            local player = game:GetService(\"Players\").LocalPlayer\n            local mouse = player:GetMouse()\n            local RunService = game:GetService(\"RunService\")\n\n            _G.AutoFireConnection = RunService.RenderStepped:Connect(function()\n                if not _G.AutoFire then return end\n\n                local target = mouse.Target\n                if target and target.Parent and target.Parent:FindFirstChild(\"Humanoid\") and target.Parent.Name ~= player.Name then\n                    mouse1press()\n                    task.wait()\n                    mouse1release()\n                end\n            end)\n        else\n            -- C2DbCaCbDeD7C0C5Cc C0C2D2Ce-D1D2D0C5CbDcC1D3\n            _G.AutoFire = false\n            if _G.AutoFireConnection then\n                _G.AutoFireConnection:Disconnect()\n                _G.AutoFireConnection = nil\n            end\n        end\n    end\n})\n\n\n\n\nlocal LeftGroupBox = Tabs.Aim:AddLeftGroupbox('gun modificator')\n\n--[[\n    AeAfB2A8AcA8A7A8B0AeA2A0AdAdA0Bf A2A5B0B1A8Bf SPREAD & RECOIL CHANGER\n    - AdC5 C2DbC7DbC2C0C5D2 CbC0C3CeC2\n    - AaCeD0D0C5CaD2CdCe C2CeC7C2D0C0D9C0C5D2 D1D2C0CdC4C0D0D2CdDbC5 D5C0D0C0CaD2C5D0C8D1D2C8CaC8\n]]\n\n-- =======================================================\n--          B7A0B1B2Bc 1: AeAfB2A8AcA8A7A8B0AeA2A0AdAdA0Bf AbAeA3A8AaA0\n--========================================================\n\n-- =======================================================\n--          B7A0B1B2Bc 1: AbAeA3A8AaA0 B1AaB0A8AfB2A0\n--========================================================\n\n-- AfC5D0C5CcC5CdCdDbC5 C4CbDf D5D0C0CdC5CdC8Df C7CdC0D7C5CdC8C9 D1Ce D1CbC0C9C4C5D0CeC2\nlocal desiredSpread = 5\nlocal desiredRecoil = 10\nlocal desiredBullets = 15 -- AdAeA2AeA5: AfC5D0C5CcC5CdCdC0Df C4CbDf CaCeCbC8D7C5D1D2C2C0 CfC0D2D0CeCdCeC2\n\n-- AfC5D0C5CcC5CdCdDbC5 C4CbDf D3CfD0C0C2CbC5CdC8Df D1CeD1D2CeDfCdC8C5Cc C8 D5D0C0CdC5CdC8Df C4C0CdCdDbD5\nlocal isChangerEnabled = false      -- B4CbC0C3, C2CaCbDeD7C5Cd CbC8 CdC0D8 D1CaD0C8CfD2\nlocal collectedStats = {}           -- AaDdD8: C7C4C5D1Dc C1D3C4D3D2 D5D0C0CdC8D2DcD1Df D1D1DbCbCaC8 CdC0 C2D1C5 CdD3C6CdDbC5 CdC0Cc CeC1DcC5CaD2Db Value\nlocal originalWeaponStats = {}    -- B0C5C7C5D0C2CdC0Df CaCeCfC8Df CeD0C8C3C8CdC0CbDcCdDbD5 D5C0D0C0CaD2C5D0C8D1D2C8Ca\nlocal hasCollected = false        -- B4CbC0C3, D7D2CeC1Db D3C1C5C4C8D2DcD1Df, D7D2Ce CcDb D1CeC1C8D0C0C5Cc C4C0CdCdDbC5 D2CeCbDcCaCe CeC4C8Cd D0C0C7\n\n--[[\n    BdD2C0 D4D3CdCaD6C8Df C2DbCfCeCbCdDfC5D2D1Df D2CeCbDcCaCe AeA4A8Ad B0A0A7.\n    AeCdC0 CdC0D5CeC4C8D2 C2D1C5 CdD3C6CdDbC5 CdC0Cc CeC1DcC5CaD2Db C8 D1CeD5D0C0CdDfC5D2 C8D5 C4CbDf C1DbD1D2D0CeC9 D0C0C1CeD2Db C2 C1D3C4D3D9C5Cc.\n]]\nlocal function collectAndBackupStats()\n    if hasCollected then return end -- A5D1CbC8 D3C6C5 D1CeC1D0C0CbC8, CdC8D7C5C3Ce CdC5 C4C5CbC0C5Cc\n\n    for _, i in pairs(game:GetService(\"ReplicatedStorage\").Weapons:GetDescendants()) do\n        -- A8A7AcA5AdA5AdAe: AfD0CeC2C5D0DfC5Cc C8 IntValue (C4CbDf CfC0D2D0CeCdCeC2) C8 NumberValue (C4CbDf C4D0D3C3C8D5 D1D2C0D2CeC2)\n        if i:IsA(\"IntValue\") or i:IsA(\"NumberValue\") then\n            -- A8A7AcA5AdA5AdAe: A4CeC1C0C2C8CbC8 \"Bullets\" C2 D1CfC8D1CeCa C4CbDf CfCeC8D1CaC0\n            if (i.Name == \"Spread\" or i.Name == \"Crouch\" or i.Name == \"Fire\" or \n                i.Name == \"InitialJump\" or i.Name == \"Jump\" or i.Name == \"Ladder\" or \n                i.Name == \"Land\" or i.Name == \"Move\" or i.Name == \"RecoveryTime\" or \n                i.Name == \"Stand\" or i.Name == \"Recoil\" or i.Name == \"Bullets\") then\n                \n                -- A4CeC1C0C2CbDfC5Cc CeC1DcC5CaD2 C2 CdC0D8 CaDdD8 C4CbDf C1DbD1D2D0CeC9 D0C0C1CeD2Db\n                table.insert(collectedStats, i)\n                -- B1CeD5D0C0CdDfC5Cc C5C3Ce CeD0C8C3C8CdC0CbDcCdCeC5 C7CdC0D7C5CdC8C5 C4CbDf C2CeC7CcCeC6CdCeD1D2C8 CeD2CaC0D2C0\n                originalWeaponStats[i] = i.Value\n            end\n        end\n    end\n    \n    hasCollected = true -- AeD2CcC5D7C0C5Cc, D7D2Ce D1C1CeD0 C7C0C2C5D0D8C5Cd\n    print(\"Weapon stats collected and backed up!\")\nend\n\n--[[\n    BdD2C0 D4D3CdCaD6C8Df CeD7C5CdDc C1DbD1D2D0C0Df. AeCdC0 CfD0CeD1D2Ce CfC5D0C5C1C8D0C0C5D2 D3C6C5 CdC0C9C4C5CdCdDbC5 CeC1DcC5CaD2Db\n    C8 CfD0C8CcC5CdDfC5D2 Ca CdC8Cc CdD3C6CdDbC5 CdC0Cc C7CdC0D7C5CdC8Df.\n]]\nlocal function applyStatChanges()\n    if not isChangerEnabled then return end -- A5D1CbC8 D1CaD0C8CfD2 C2DbCaCbDeD7C5Cd, CdC8D7C5C3Ce CdC5 C4C5CbC0C5Cc\n\n    for _, statObject in ipairs(collectedStats) do\n        if statObject and statObject.Parent then\n            -- A8A7AcA5AdA5AdAe: A4CeC1C0C2CbC5CdC0 CbCeC3C8CaC0 C4CbDf CfC0D2D0CeCdCeC2 C8 D3CbD3D7D8C5CdC0 D1D2D0D3CaD2D3D0C0 if/else\n            if statObject.Name == \"Recoil\" then\n                statObject.Value = desiredRecoil\n            elseif statObject.Name == \"Bullets\" then\n                statObject.Value = desiredBullets\n            else -- A2D1C5 CeD1D2C0CbDcCdDbC5 D5C0D0C0CaD2C5D0C8D1D2C8CaC8 (Spread, Crouch, Move C8 D2.C4.) C1D3C4D3D2 C8D1CfCeCbDcC7CeC2C0D2Dc C7CdC0D7C5CdC8C5 D0C0C7C1D0CeD1C0\n                statObject.Value = desiredSpread\n            end\n        end\n    end\nend\n\n-- B4D3CdCaD6C8Df C4CbDf C2CeC7C2D0C0D2C0 CeD0C8C3C8CdC0CbDcCdDbD5 D5C0D0C0CaD2C5D0C8D1D2C8Ca\nlocal function revertStatChanges()\n    for statObject, originalValue in pairs(originalWeaponStats) do\n        if statObject and statObject.Parent then\n            statObject.Value = originalValue\n        end\n    end\nend\n\n-- A3CbC0C2CdC0Df D4D3CdCaD6C8Df, CaCeD2CeD0D3De C2DbC7DbC2C0C5D2 CfC5D0C5CaCbDeD7C0D2C5CbDc (Toggle)\nlocal function toggleStatChanger(enabled)\n    isChangerEnabled = enabled\n\n    if isChangerEnabled then\n        -- AfD0C8 CfC5D0C2CeCc C2CaCbDeD7C5CdC8C8, D1CeC1C8D0C0C5Cc C2D1C5 C4C0CdCdDbC5\n        collectAndBackupStats()\n        -- A8 D1D0C0C7D3 CfD0C8CcC5CdDfC5Cc CdC0D8C8 CaC0D1D2CeCcCdDbC5 CdC0D1D2D0CeC9CaC8\n        applyStatChanges()\n    else\n        -- AfD0C8 C2DbCaCbDeD7C5CdC8C8, C2CeC7C2D0C0D9C0C5Cc C2D1C5 CaC0Ca C1DbCbCe\n        revertStatChanges()\n    end\nend\n\n-- AcDb D2C0CaC6C5 C4CeCbC6CdDb CfD0C8CcC5CdDfD2Dc CdC0D1D2D0CeC9CaC8 CaC0C6C4DbC9 D0C0C7, CaCeC3C4C0 C8C3D0CeCa C1C5D0C5D2 C2 D0D3CaC8 CdCeC2CeC5 CeD0D3C6C8C5,\n-- D2C0Ca CaC0Ca C8C3D0C0 CcCeC6C5D2 D1C1D0C0D1DbC2C0D2Dc C5C3Ce D5C0D0C0CaD2C5D0C8D1D2C8CaC8.\ngame.Players.LocalPlayer.CharacterAdded:Connect(function(character)\n    character.ChildAdded:Connect(function(child)\n        if child:IsA(\"Tool\") then\n            -- A4C0C5Cc CdC5C1CeCbDcD8D3De C7C0C4C5D0C6CaD3, D7D2CeC1Db C2D1C5 D5C0D0C0CaD2C5D0C8D1D2C8CaC8 CeD0D3C6C8Df D3D1CfC5CbC8 C7C0C3D0D3C7C8D2DcD1Df\n            task.wait(0.1)\n            -- AfCeC2D2CeD0CdCe CfD0C8CcC5CdDfC5Cc CdC0D8C8 CdC0D1D2D0CeC9CaC8, C5D1CbC8 D7C8D2 C2CaCbDeD7C5Cd\n            applyStatChanges()\n        end\n    end)\nend)\n\n\n-- =======================================================\n--          B7A0B1B2Bc 2: UI (C4CeC1C0C2CbC5Cd CdCeC2DbC9 D1CbC0C9C4C5D0)\n--========================================================\n\nLeftGroupBox:AddToggle('Apply Weapon Mods', {\n    Text = 'Apply Weapon Mods',\n    Tooltip = '',\n    Default = false, -- AfCe D3CcCeCbD7C0CdC8De C2DbCaCbDeD7C5CdCe\n    Callback = function(Value)\n        toggleStatChanger(Value)\n    end\n})\n\nLeftGroupBox:AddSlider('Spread Changer', {\n    Text = 'Spread Value',\n    Default = 5,\n    Min = 0,\n    Max = 10,\n    Rounding = 1,\n    Compact = false,\n    Callback = function(value)\n        desiredSpread = value\n        -- B1D0C0C7D3 CfD0C8CcC5CdDfC5Cc CdCeC2CeC5 C7CdC0D7C5CdC8C5, C5D1CbC8 D7C8D2 D3C6C5 C2CaCbDeD7C5Cd\n        applyStatChanges()\n    end,\n    Tooltip = '',\n})\n\nLeftGroupBox:AddSlider('Recoil Changer', {\n    Text = 'Recoil Value',\n    Default = 10,\n    Min = 0,\n    Max = 35,\n    Rounding = 1,\n    Compact = false,\n    Callback = function(value)\n        desiredRecoil = value\n        -- B1D0C0C7D3 CfD0C8CcC5CdDfC5Cc CdCeC2CeC5 C7CdC0D7C5CdC8C5, C5D1CbC8 D7C8D2 D3C6C5 C2CaCbDeD7C5Cd\n        applyStatChanges()\n    end,\n    Tooltip = '',\n})\n\n-- AdAeA2AeA5: B1CbC0C9C4C5D0 C4CbDf C8C7CcC5CdC5CdC8Df CaCeCbC8D7C5D1D2C2C0 CfC0D2D0CeCdCeC2\nLeftGroupBox:AddSlider('Bullets Changer', {\n    Text = 'bullet',\n    Default = 15,\n    Min = 1,\n    Max = 25, -- AcCeC6CdCe CfCeD1D2C0C2C8D2Dc C1CeCbDcD8C5, C5D1CbC8 CdD3C6CdCe\n    Rounding = 0, -- AfC0D2D0CeCdDb C4CeCbC6CdDb C1DbD2Dc D6C5CbDbCc D7C8D1CbCeCc\n    Compact = false,\n    Callback = function(value)\n        desiredBullets = value\n        -- B1D0C0C7D3 CfD0C8CcC5CdDfC5Cc CdCeC2CeC5 C7CdC0D7C5CdC8C5, C5D1CbC8 D7C8D2 D3C6C5 C2CaCbDeD7C5Cd\n        applyStatChanges()\n    end,\n    Tooltip = 'Tap',\n})\n\n\n\n\n-- B2C0C1CbC8D6C0 C4CbDf D5D0C0CdC5CdC8Df CeD0C8C3C8CdC0CbDcCdDbD5 C7CdC0D7C5CdC8C9 D1CaCeD0CeD1D2D0C5CbDcCdCeD1D2C8\nlocal originalFireRates = {}\n\nLeftGroupBox:AddToggle('No Fire Rate', {\n    Text = 'No Fire Rate',\n    Tooltip = '',\n    Default = false, -- AfCe D3CcCeCbD7C0CdC8De C2DbCaCbDeD7C5CdCe\n    Callback = function(Value)\n        -- AfCeCbD3D7C0C5Cc CfC0CfCaD3 D1 CeD0D3C6C8C5Cc\n        local weaponsFolder = game:GetService(\"ReplicatedStorage\").Weapons\n\n        -- AfD0CeD5CeC4C8CcD1Df CfCe C2D1C5CcD3 CeD0D3C6C8De C2 CfC0CfCaC5\n        for _, weapon in ipairs(weaponsFolder:GetChildren()) do\n            -- AfD0CeC2C5D0DfC5Cc, C5D1D2Dc CbC8 D3 CeD0D3C6C8Df C7CdC0D7C5CdC8C5 FireRate\n            if weapon:FindFirstChild(\"FireRate\") then\n                local fireRateValue = weapon.FireRate\n\n                if Value then\n                    -- A5D1CbC8 D4D3CdCaD6C8Df C2CaCbDeD7C5CdC0\n                    -- B1CeD5D0C0CdDfC5Cc CeD0C8C3C8CdC0CbDcCdCeC5 C7CdC0D7C5CdC8C5, C5D1CbC8 CeCdCe C5D9C5 CdC5 D1CeD5D0C0CdC5CdCe\n                    if not originalFireRates[weapon] then\n                        originalFireRates[weapon] = fireRateValue.Value\n                    end\n                    -- B3D1D2C0CdC0C2CbC8C2C0C5Cc D1CaCeD0CeD1D2D0C5CbDcCdCeD1D2Dc CdC0 0\n                    fireRateValue.Value = 0\n                else\n                    -- A5D1CbC8 D4D3CdCaD6C8Df C2DbCaCbDeD7C5CdC0\n                    -- A2CeD1D1D2C0CdC0C2CbC8C2C0C5Cc CeD0C8C3C8CdC0CbDcCdCeC5 C7CdC0D7C5CdC8C5, C5D1CbC8 CeCdCe C1DbCbCe D1CeD5D0C0CdC5CdCe\n                    if originalFireRates[weapon] then\n                        fireRateValue.Value = originalFireRates[weapon]\n                    end\n                end\n            end\n        end\n    end\n})\n\n\n\n\nlocal RightGroupBox = Tabs.Aim:AddRightGroupbox('Other')\n\n\n\n-- B1CbD3C6C1Db Roblox\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal Workspace = game:GetService(\"Workspace\")\n\n-- AbCeCaC0CbDcCdDbC9 C8C3D0CeCa C8 CaC0CcC5D0C0\nlocal localPlayer = Players.LocalPlayer\nlocal camera = Workspace.CurrentCamera\n\n-- AcC0D2C5D0C8C0CbDb, D7C5D0C5C7 CaCeD2CeD0DbC5 CcCeC6CdCe D1D2D0C5CbDfD2Dc\nlocal PenetrableMaterials = {\n\t[Enum.Material.WoodPlanks] = true,\n\t[Enum.Material.Wood] = true,\n\t[Enum.Material.Plastic] = true,\n\t[Enum.Material.Glass] = true,\n\t[Enum.Material.CorrodedMetal] = true,\n\t[Enum.Material.Grass] = true,\n\t[Enum.Material.LeafyGrass] = true,\n\t[Enum.Material.Mud] = true,\n\t[Enum.Material.Sand] = true,\n\t[Enum.Material.Snow] = true,\n\t[Enum.Material.Ice] = true,\n\t[Enum.Material.Asphalt] = true,\n\t[Enum.Material.Rock] = true,\n\t[Enum.Material.Rubber] = true,\n\t[Enum.Material.Metal] = true,\n\t[Enum.Material.CorrodedMetal] = true,\n\t[Enum.Material.DiamondPlate] = true,\n\t[Enum.Material.Concrete] = true,\n\t[Enum.Material.Cobblestone] = true,\n\t[Enum.Material.ClayRoofTiles] = true,\n}\n-- AcC0CaD1C8CcC0CbDcCdC0Df D2CeCbD9C8CdC0 D1D2C5CdDb C4CbDf CfD0CeD1D2D0C5CbC0\nlocal maxPenetrationDepth = 45\n\n-- A3CbCeC1C0CbDcCdDbC5 CfC5D0C5CcC5CdCdDbC5\n_G.AutoFire = false\n_G.AutoFireConnection = nil\n\n-- =======================================================\n--          B4B3AdAaB6A8Bf A2AaAbBeB7A5AdA8Bf / A2BbAaAbBeB7A5AdA8Bf AUTO FIRE\n--========================================================\nlocal function toggleAutoFire(enabled)\n\tif enabled then\n\t\tif _G.AutoFireConnection then return end\n\t\t_G.AutoFire = true\n\n\t\t_G.AutoFireConnection = RunService.RenderStepped:Connect(function()\n\t\t\tif not _G.AutoFire then return end\n\t\t\tif not localPlayer.Character or not Workspace.CurrentCamera then return end\n\n\t\t\tlocal targetVisible = false\n\n\t\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\t\tif player == localPlayer then continue end\n\t\t\t\tif not player.Character or not player.Character:FindFirstChild(\"HumanoidRootPart\") then continue end\n\t\t\t\tif player.Team and localPlayer.Team and player.Team == localPlayer.Team then continue end\n\n\t\t\t\tlocal targetCharacter = player.Character\n\t\t\t\tlocal targetPosition = targetCharacter.HumanoidRootPart.Position\n\t\t\t\tlocal _, onScreen = camera:WorldToScreenPoint(targetPosition)\n\t\t\t\tif not onScreen then continue end\n\n\t\t\t\tlocal origin = camera.CFrame.Position\n\t\t\t\tlocal direction = (targetPosition - origin).Unit\n\n\t\t\t\t-- AeD1CdCeC2CdCeC9 CbD3D7\n\t\t\t\tlocal mainRayParams = RaycastParams.new()\n\t\t\t\tmainRayParams.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\tmainRayParams.FilterDescendantsInstances = {localPlayer.Character}\n\t\t\t\tlocal mainResult = Workspace:Raycast(origin, direction * 2000, mainRayParams)\n\n\t\t\t\tif mainResult and mainResult.Instance then\n\t\t\t\t\t-- 1þ0f e3 AfD0DfCcC0Df C2C8C4C8CcCeD1D2Dc\n\t\t\t\t\tif mainResult.Instance:IsDescendantOf(targetCharacter) then\n\t\t\t\t\t\ttargetVisible = true\n\t\t\t\t\t\tbreak\n\t\t\t\t\t-- 2þ0f e3 AfD0CeD1D2D0C5Cb D7C5D0C5C7 D1D2C5CdDb\n\t\t\t\t\telseif PenetrableMaterials[mainResult.Instance.Material] then\n\t\t\t\t\t\t-- ================= B1B2A5AdA0 1 =================\n\t\t\t\t\t\tlocal wall1 = mainResult.Instance\n\t\t\t\t\t\tlocal entry1 = mainResult.Position\n\n\t\t\t\t\t\tlocal reverseParams1 = RaycastParams.new()\n\t\t\t\t\t\treverseParams1.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\treverseParams1.FilterDescendantsInstances = {localPlayer.Character}\n\t\t\t\t\t\tlocal reverseResult1 = Workspace:Raycast(targetPosition, (origin - targetPosition).Unit * 2000, reverseParams1)\n\n\t\t\t\t\t\tif reverseResult1 and (entry1 - reverseResult1.Position).Magnitude <= maxPenetrationDepth then\n\t\t\t\t\t\t\tlocal exit1 = reverseResult1.Position\n\t\t\t\t\t\t\t\n\t\t\t\t\t\t\tlocal ray2Params = RaycastParams.new()\n\t\t\t\t\t\t\tray2Params.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\t\tray2Params.FilterDescendantsInstances = {localPlayer.Character, wall1}\n\t\t\t\t\t\t\tlocal ray2Result = Workspace:Raycast(exit1, direction * 2000, ray2Params)\n\n\t\t\t\t\t\t\tif ray2Result and ray2Result.Instance:IsDescendantOf(targetCharacter) then\n\t\t\t\t\t\t\t\ttargetVisible = true\n\t\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\t\t-- ================= B1B2A5AdA0 2 =================\n\t\t\t\t\t\t\telseif ray2Result and PenetrableMaterials[ray2Result.Instance.Material] then\n\t\t\t\t\t\t\t\tlocal wall2 = ray2Result.Instance\n\t\t\t\t\t\t\t\tlocal entry2 = ray2Result.Position\n\n\t\t\t\t\t\t\t\tlocal reverseParams2 = RaycastParams.new()\n\t\t\t\t\t\t\t\treverseParams2.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\t\t\treverseParams2.FilterDescendantsInstances = {localPlayer.Character, wall1}\n\t\t\t\t\t\t\t\tlocal reverseResult2 = Workspace:Raycast(targetPosition, (origin - targetPosition).Unit * 2000, reverseParams2)\n\n\t\t\t\t\t\t\t\tif reverseResult2 and (entry2 - reverseResult2.Position).Magnitude <= maxPenetrationDepth then\n\t\t\t\t\t\t\t\t\tlocal exit2 = reverseResult2.Position\n\n\t\t\t\t\t\t\t\t\tlocal ray3Params = RaycastParams.new()\n\t\t\t\t\t\t\t\t\tray3Params.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\t\t\t\tray3Params.FilterDescendantsInstances = {localPlayer.Character, wall1, wall2}\n\t\t\t\t\t\t\t\t\tlocal ray3Result = Workspace:Raycast(exit2, direction * 2000, ray3Params)\n\n\t\t\t\t\t\t\t\t\tif ray3Result and ray3Result.Instance:IsDescendantOf(targetCharacter) then\n\t\t\t\t\t\t\t\t\t\ttargetVisible = true\n\t\t\t\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\t\t\t\t-- ================= B1B2A5AdA0 3 =================\n\t\t\t\t\t\t\t\t\telseif ray3Result and PenetrableMaterials[ray3Result.Instance.Material] then\n\t\t\t\t\t\t\t\t\t\tlocal wall3 = ray3Result.Instance\n\t\t\t\t\t\t\t\t\t\tlocal entry3 = ray3Result.Position\n\n\t\t\t\t\t\t\t\t\t\tlocal reverseParams3 = RaycastParams.new()\n\t\t\t\t\t\t\t\t\t\treverseParams3.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\t\t\t\t\treverseParams3.FilterDescendantsInstances = {localPlayer.Character, wall1, wall2}\n\t\t\t\t\t\t\t\t\t\tlocal reverseResult3 = Workspace:Raycast(targetPosition, (origin - targetPosition).Unit * 2000, reverseParams3)\n\n\t\t\t\t\t\t\t\t\t\tif reverseResult3 and (entry3 - reverseResult3.Position).Magnitude <= maxPenetrationDepth then\n\t\t\t\t\t\t\t\t\t\t\tlocal exit3 = reverseResult3.Position\n\n\t\t\t\t\t\t\t\t\t\t\tlocal ray4Params = RaycastParams.new()\n\t\t\t\t\t\t\t\t\t\t\tray4Params.FilterType = Enum.RaycastFilterType.Exclude\n\t\t\t\t\t\t\t\t\t\t\tray4Params.FilterDescendantsInstances = {localPlayer.Character, wall1, wall2, wall3}\n\t\t\t\t\t\t\t\t\t\t\tlocal ray4Result = Workspace:Raycast(exit3, direction * 2000, ray4Params)\n\t\t\t\t\t\t\t\t\t\t\t\n\t\t\t\t\t\t\t\t\t\t\tif ray4Result and ray4Result.Instance:IsDescendantOf(targetCharacter) then\n\t\t\t\t\t\t\t\t\t\t\t\ttargetVisible = true\n\t\t\t\t\t\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\t\tend\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\n\t\t\t-- A5D1CbC8 C5D1D2Dc C2C8C4C8CcC0Df D6C5CbDc  14 D1D2D0C5CbDfC5Cc\n\t\t\tif targetVisible then\n\t\t\t\tmouse1press()\n\t\t\t\ttask.wait(0.05)\n\t\t\t\tmouse1release()\n\t\t\tend\n\t\tend)\n\telse\n\t\t-- A2DbCaCbDeD7C0C5Cc\n\t\t_G.AutoFire = false\n\t\tif _G.AutoFireConnection then\n\t\t\t_G.AutoFireConnection:Disconnect()\n\t\t\t_G.AutoFireConnection = nil\n\t\tend\n\tend\nend\n\n-- =======================================================\n--          B7A0B1B2Bc 2: UI (C1C5C7 C8C7CcC5CdC5CdC8C9)\n--========================================================\nRightGroupBox:AddToggle('Auto Fire', {\n\tText = 'Auto Fire',\n\tTooltip = 'Auto Fire',\n\tCallback = function(Value)\n\t\ttoggleAutoFire(Value)\n\tend\n})\n\n\n\n-- B2C0C1CbC8D6C0 C4CbDf D5D0C0CdC5CdC8Df CeD0C8C3C8CdC0CbDcCdDbD5 C7CdC0D7C5CdC8C9 CfD0CeC1C8C2C0CdC8Df C4CbDf CaC0C6C4CeC3Ce CeD0D3C6C8Df.\n-- AcDb CeC1DaDfC2CbDfC5Cc C5E1 D1CdC0D0D3C6C8, D7D2CeC1Db CeCdC0 CdC5 D1C1D0C0D1DbC2C0CbC0D1Dc CfD0C8 CaC0C6C4CeCc CdC0C6C0D2C8C8.\nlocal originalValues = {}\n\nRightGroupBox:AddToggle('Penetration', {\n    Text = 'Penetration',\n    Tooltip = 'Penetration',\n    Callback = function(Value)\n        -- AeCfD0C5C4C5CbDfC5Cc CfD3D2Dc Ca CfC0CfCaC5 D1 CeD0D3C6C8C5Cc.\n        local weaponsFolder = game:GetService(\"ReplicatedStorage\"):FindFirstChild(\"Weapons\")\n\n        -- AfD0CeC2C5D0DfC5Cc, D1D3D9C5D1D2C2D3C5D2 CbC8 CfC0CfCaC0 D1 CeD0D3C6C8C5Cc, D7D2CeC1Db C8C7C1C5C6C0D2Dc CeD8C8C1CeCa.\n        if not weaponsFolder then\n            print(\"\")\n            return\n        end\n\n        if Value == true then\n            -- --- AbAeA3A8AaA0 A2AaAbBeB7A5AdA8Bf B7A8B2A0 ---\n\n            -- AeD7C8D9C0C5Cc D1D2C0D0DbC5 D1CeD5D0C0CdC5CdCdDbC5 C7CdC0D7C5CdC8Df CdC0 D1CbD3D7C0C9, C5D1CbC8 CeCdC8 CeD1D2C0CbC8D1Dc.\n            originalValues = {}\n\n            -- AfC5D0C5C1C8D0C0C5Cc CaC0C6C4CeC5 CeD0D3C6C8C5 C2 CfC0CfCaC5.\n            for _, weapon in ipairs(weaponsFolder:GetChildren()) do\n                -- A8D9C5Cc CfC0D0C0CcC5D2D0Db Penetration C8 ArmorPenetration C2 D2C5CaD3D9C5Cc CeD0D3C6C8C8.\n                local penetration = weapon:FindFirstChild(\"Penetration\")\n                local armorPenetration = weapon:FindFirstChild(\"ArmorPenetration\")\n\n                originalValues[weapon] = {} -- B1CeC7C4C0C5Cc CfCeC4-D2C0C1CbC8D6D3 C4CbDf DdD2CeC3Ce CeD0D3C6C8Df.\n\n                if penetration then\n                    -- B1CeD5D0C0CdDfC5Cc CeD0C8C3C8CdC0CbDcCdCeC5 C7CdC0D7C5CdC8C5 CfC5D0C5C4 D2C5Cc, CaC0Ca C5C3Ce C8C7CcC5CdC8D2Dc.\n                    originalValues[weapon].Penetration = penetration.Value\n                    -- B3D1D2C0CdC0C2CbC8C2C0C5Cc CdCeC2CeC5, CeC3D0CeCcCdCeC5 C7CdC0D7C5CdC8C5.\n                    penetration.Value = 100000000\n                end\n\n                if armorPenetration then\n                    -- B1CeD5D0C0CdDfC5Cc CeD0C8C3C8CdC0CbDcCdCeC5 C7CdC0D7C5CdC8C5.\n                    originalValues[weapon].ArmorPenetration = armorPenetration.Value\n                    -- B3D1D2C0CdC0C2CbC8C2C0C5Cc CdCeC2CeC5 C7CdC0D7C5CdC8C5.\n                    armorPenetration.Value = 100000000\n                end\n            end\n            print(\"\")\n\n        else\n            -- --- AbAeA3A8AaA0 A2BbAaAbBeB7A5AdA8Bf B7A8B2A0 ---\n\n            -- AfC5D0C5C1C8D0C0C5Cc CeD0D3C6C8C5 D1CdCeC2C0, D7D2CeC1Db C2CeD1D1D2C0CdCeC2C8D2Dc C8D1D5CeC4CdDbC5 C7CdC0D7C5CdC8Df.\n            for _, weapon in ipairs(weaponsFolder:GetChildren()) do\n                -- AfD0CeC2C5D0DfC5Cc, C5D1D2Dc CbC8 C4CbDf DdD2CeC3Ce CeD0D3C6C8Df D1CeD5D0C0CdC5CdCdDbC5 C7CdC0D7C5CdC8Df.\n                if originalValues[weapon] then\n                    local penetration = weapon:FindFirstChild(\"Penetration\")\n                    local armorPenetration = weapon:FindFirstChild(\"ArmorPenetration\")\n\n                    -- A5D1CbC8 CcDb D1CeD5D0C0CdDfCbC8 C7CdC0D7C5CdC8C5 'Penetration', C2CeD1D1D2C0CdC0C2CbC8C2C0C5Cc C5C3Ce.\n                    if penetration and originalValues[weapon].Penetration then\n                        penetration.Value = originalValues[weapon].Penetration\n                    end\n\n                    -- A5D1CbC8 CcDb D1CeD5D0C0CdDfCbC8 'ArmorPenetration', C2CeD1D1D2C0CdC0C2CbC8C2C0C5Cc C5C3Ce.\n                    if armorPenetration and originalValues[weapon].ArmorPenetration then\n                        armorPenetration.Value = originalValues[weapon].ArmorPenetration\n                    end\n                end\n            end\n            \n            -- AeD7C8D9C0C5Cc D2C0C1CbC8D6D3, D2C0Ca CaC0Ca C7CdC0D7C5CdC8Df C2CeD1D1D2C0CdCeC2CbC5CdDb.\n            originalValues = {}\n            print(\"\")\n        end\n    end\n})\n\n\n\n\n\nlocal LeftGroupBox = Tabs.Misc:AddLeftGroupbox('Other')\n\n\n\n\n\n\n-- UI toggle\nLeftGroupBox:AddToggle('KillSay', {  \n\tText = 'KillSay',  \n\tDefault = false,\n\tCallback = function(state)\n\t\tgetgenv().KillSayEnabled = state\n\tend\n})\n\n-- AeD1CdCeC2CdC0Df CbCeC3C8CaC0\nlocal player = game.Players.LocalPlayer\nlocal additionals = player:WaitForChild(\"Additionals\")\nlocal totalDamage = additionals:WaitForChild(\"TotalDamage\")\n\n-- B1CfC8D1CeCa D1CeCeC1D9C5CdC8C9\nlocal tauntMessages = {\n\t\"get good\",\n\t\"ez\",\n\t\"skill issue?\",\n\t\"was that supposed to be a challenge?\",\n\t\"try again\",\n\t\"nice try lol\",\n\t\"better luck next time\",\n\t\"are you even trying?\",\n\t\"get tapped\",\n\t\"your settings need help\",\n\t\"I don 19t miss  14 it 19s tradition\",\n\t\"missed due to script issue\",\n\t\"easy for gamescript\",\n\t\"skido ware try to kill me\",\n\t\"give up\",\n\t\"i never lose\",\n\t\"neverlose with game script\",\n\t\"stop trying to kill me\",\n\t\"I use 20% of my script\",\n\t\"gg = get good\",\n\t\"gg\"\n}\n\n-- AaC0C6C4DbC5 100 D3D0CeCdC0  14 CeC4CdCe D1CeCeC1D9C5CdC8C5\nlocal damageStep = 100\nlocal nextDamageMilestone = damageStep\n\ntotalDamage.Changed:Connect(function(newValue)\n\tif not getgenv().KillSayEnabled then return end -- AfD0CeC2C5D0DfC5Cc, C2CaCbDeD7E1Cd CbC8 KillSay\n\n\tif newValue >= nextDamageMilestone then\n\t\tlocal randomMessage = tauntMessages[math.random(#tauntMessages)]\n\n\t\t-- AeD2CfD0C0C2CbDfC5Cc D1CeCeC1D9C5CdC8C5 C2 D7C0D2 (D7C5D0C5C7 RemoteEvent)\n\t\tgame:GetService(\"ReplicatedStorage\"):WaitForChild(\"Events\"):WaitForChild(\"PlayerChatted\"):FireServer(randomMessage, false)\n\n\t\tnextDamageMilestone = nextDamageMilestone + damageStep\n\tend\nend)\n\n\n\n\n\nlocal RightGroupBox = Tabs.Misc:AddRightGroupbox('Movement')\n\n\n\n\n\n\n\n\n\n\n--// B2D3CcC1CbC5D0 C4CbDf C2CaCbDeD7C5CdC8Df Bhop\nRightGroupBox:AddToggle('Bhop', {  \n\tText = 'Bhop',  \n\tDefault = false,\n\tCallback = function(Value)\n\t\t_G.Bhop = Value\n\tend\n})\n\n--// B1CbC0C9C4C5D0 C4CbDf D1CaCeD0CeD1D2C8 Bhop\nRightGroupBox:AddSlider('BhopSpeed', { \n\tText = 'Bhop speed',\n\tDefault = 100, \n\tMin = 0,\n\tMax = 500, \n\tRounding = 1,\n\tCompact = false,\n\tCallback = function(Value)\n\t\t_G.BhopSpeed = Value\n\tend\n})\n\n--// B1C5D0C2C8D1Db Roblox\nlocal RunService = game:GetService(\"RunService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\nlocal Camera = workspace.CurrentCamera\n\n--// AeD1CdCeC2CdCeC9 D6C8CaCb BunnyHop\nRunService.RenderStepped:Connect(function()\n\tif _G.Bhop then\n\t\tif LocalPlayer.Character \n\t\t\tand UserInputService:IsKeyDown(Enum.KeyCode.Space)\n\t\t\tand LocalPlayer:FindFirstChild(\"PlayerGui\")\n\t\t\tand LocalPlayer.PlayerGui:FindFirstChild(\"GUI\")\n\t\t\tand LocalPlayer.PlayerGui.GUI.Main.GlobalChat.Visible == false\n\t\tthen\n\t\t\tlocal Humanoid = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n\t\t\tlocal HRP = LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n\n\t\t\tif Humanoid and HRP then\n\t\t\t\tHumanoid.Jump = true\n\t\t\t\tlocal Speed = _G.BhopSpeed or 100\n\n\t\t\t\tlocal Dir = Camera.CFrame.LookVector * Vector3.new(1, 0, 1)\n\t\t\t\tlocal Move = Vector3.zero\n\n\t\t\t\tif UserInputService:IsKeyDown(Enum.KeyCode.W) then\n\t\t\t\t\tMove += Dir\n\t\t\t\tend\n\t\t\t\tif UserInputService:IsKeyDown(Enum.KeyCode.S) then\n\t\t\t\t\tMove -= Dir\n\t\t\t\tend\n\t\t\t\tif UserInputService:IsKeyDown(Enum.KeyCode.D) then\n\t\t\t\t\tMove += Vector3.new(-Dir.Z, 0, Dir.X)\n\t\t\t\tend\n\t\t\t\tif UserInputService:IsKeyDown(Enum.KeyCode.A) then\n\t\t\t\t\tMove += Vector3.new(Dir.Z, 0, -Dir.X)\n\t\t\t\tend\n\n\t\t\t\tif Move.Magnitude > 0 then\n\t\t\t\t\tMove = Move.Unit\n\t\t\t\t\tHRP.Velocity = Vector3.new(Move.X * Speed, HRP.Velocity.Y, Move.Z * Speed)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend)\n\n\n\n\nlocal LeftGroupBox = Tabs.AntiAim:AddLeftGroupbox('Anti Aims')\n\n\n\n\n-- ===================================================================\n-- B1AaB0A8AfB2 1: BACKWARD (B5AeA4BcA1A0 B1AfA8AdAeA9)\n-- ===================================================================\n\n-- B1CeC7C4C0C5Cc CfC5D0C5CaCbDeD7C0D2C5CbDc C4CbDf D5CeC4DcC1Db D1CfC8CdCeC9\nLeftGroupBox:AddToggle('Backward', {\n    Text = 'Backward',\n    Default = false,\n    Callback = function(Value)\n        getgenv().backward = Value\n    end\n})\n\n-- AbCeC3C8CaC0 C4CbDf D5CeC4DcC1Db D1CfC8CdCeC9\nlocal plr = game:GetService(\"Players\").LocalPlayer\nlocal runService = game:GetService(\"RunService\")\nlocal main_camera = workspace.CurrentCamera\n\ngetgenv().backward = getgenv().backward or false\n\nrunService.RenderStepped:Connect(function()\n    local character = plr.Character\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local hrp = character and character:FindFirstChild(\"HumanoidRootPart\")\n\n    if not (humanoid and hrp) then return end\n\n    if getgenv().backward then\n        -- B0A5A6A8Ac A2AaAbBeB7A5Ad:\n        humanoid.AutoRotate = false\n        hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(main_camera.CFrame.Position.X, hrp.Position.Y, main_camera.CFrame.Position.Z))\n    else\n        -- B0A5A6A8Ac A2BbAaAbBeB7A5Ad:\n        if not humanoid.AutoRotate then\n            humanoid.AutoRotate = true\n        end\n    end\nend)\n\n\n-- ===================================================================\n-- B1AaB0A8AfB2 2: PITCH CHANGER (A8A7AcA5AdA5AdA8A5 AdA0AaAbAeAdA0 AaA0AcA5B0Bb)\n-- ===================================================================\n\n-- 1. B1CeC7C4C0C5Cc CfC5D0C5CcC5CdCdDbC5 C4CbDf D3CfD0C0C2CbC5CdC8Df\ngetgenv().pitchChangerEnabled = false\ngetgenv().currentPitchValue = 0\n\n-- 2. AdC0D5CeC4C8Cc CdD3C6CdDbC9 C8C2C5CdD2\nlocal controlTurnEvent = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Events\"):WaitForChild(\"ControlTurn\")\n\n-- 3. A7C0CfD3D1CaC0C5Cc D4CeCdCeC2DbC9 D6C8CaCb, CaCeD2CeD0DbC9 C4C5CbC0C5D2 C2D1De D0C0C1CeD2D3\ntask.spawn(function()\n    while task.wait() do\n        if getgenv().pitchChangerEnabled then\n            local pitchToSend = getgenv().currentPitchValue / 10\n            \n            pcall(function()\n                controlTurnEvent:FireServer(pitchToSend, false)\n            end)\n        end\n    end\nend)\n\n-- 4. B1CeC7C4C0C5Cc CaCdCeCfCaD3-CfC5D0C5CaCbDeD7C0D2C5CbDc C4CbDf Pitch Changer\nLeftGroupBox:AddToggle('pitch changer', {\n    Text = 'pitch changer',\n    Tooltip = 'pitch changer', \n    Callback = function(Value)\n        getgenv().pitchChangerEnabled = Value\n    end\n})\n\n-- 5. B1CeC7C4C0C5Cc D1CbC0C9C4C5D0 C4CbDf D3CfD0C0C2CbC5CdC8Df C7CdC0D7C5CdC8C5Cc CdC0CaCbCeCdC0\nLeftGroupBox:AddSlider('pitch value', {\n    Text = 'pitch value',\n    Tooltip = 'pitch changer',\n    Default = 0,\n    Min = -9,\n    Max = 9,\n    Rounding = 1,\n    Compact = false,\n    Callback = function(SliderValue)\n        getgenv().currentPitchValue = SliderValue\n    end\n})\n\n\nlocal MenuGroup = Tabs['UI Settings']:AddLeftGroupbox('Menu')\n\nMenuGroup:AddToggle(\"KeybindMenuOpen\", { Default = Library.KeybindFrame.Visible, Text = \"Open Keybind Menu\", Callback = function(value) Library.KeybindFrame.Visible = value end})\nMenuGroup:AddToggle(\"ShowCustomCursor\", {Text = \"Custom Cursor\", Default = true, Callback = function(Value) Library.ShowCustomCursor = Value end})\nMenuGroup:AddDivider()\nMenuGroup:AddLabel(\"Menu bind\"):AddKeyPicker(\"MenuKeybind\", { Default = \"RightShift\", NoUI = true, Text = \"Menu keybind\" })\nMenuGroup:AddButton(\"Unload\", function() Library:Unload() end)\n\nLibrary.ToggleKeybind = Options.MenuKeybind -- Allows you to have a custom keybind for the menu\n\n-- Addons:\n-- SaveManager (Allows you to have a configuration system)\n-- ThemeManager (Allows you to have a menu theme system)\n\n-- Hand the library over to our managers\nThemeManager:SetLibrary(Library)\nSaveManager:SetLibrary(Library)\n\n-- Ignore keys that are used by ThemeManager.\n-- (we dont want configs to save themes, do we?)\nSaveManager:IgnoreThemeSettings()\n\n-- Adds our MenuKeybind to the ignore list\n-- (do you want each config to have a different menu key? probably not.)\nSaveManager:SetIgnoreIndexes({ 'MenuKeybind' })\n\n-- use case for doing it this way:\n-- a script hub could have themes in a global folder\n-- and game configs in a separate folder per game\nThemeManager:SetFolder('MyScriptHub')\nSaveManager:SetFolder('MyScriptHub/specific-game')\nSaveManager:SetSubFolder('specific-place') -- if the game has multiple places inside of it (for example: DOORS) \n\t\t\t\t\t   -- you can use this to save configs for those places separately\n\t\t\t\t\t   -- The path in this script would be: MyScriptHub/specific-game/settings/specific-place\n\t\t\t\t\t   -- [ This is optional ]\n\n-- Builds our config menu on the right side of our tab\nSaveManager:BuildConfigSection(Tabs['UI Settings'])\n\n-- Builds our theme menu (with plenty of built in themes) on the left side\n-- NOTE: you can also call ThemeManager:ApplyToGroupbox to add it to a specific groupbox\nThemeManager:ApplyToTab(Tabs['UI Settings'])\n\n-- You can use the SaveManager:LoadAutoloadConfig() to load a config\n-- which has been marked to be one that auto loads!\nSaveManager:LoadAutoloadConfig()")();